app.use('/api/processed', express.static(PROCESSED_DIR));

/**
 * Robust Image Loader Helper
 * Tries to load image with Sharp directly.
 * If that fails (common with legacy BMPs), falls back to bmp-js decoding.
 */
async function getSharpInstance(filePath) {
  const ext = path.extname(filePath).toLowerCase();

  try {
    // 1. Try standard Sharp loading first.
    const instance = sharp(filePath, { 
      failOnError: false, 
      limitInputPixels: false 
    });

    // Check Metadata to ensure file is readable
    const metadata = await instance.metadata(); 

    // Specific check for files that are TRULY BMP but might be unsupported by libvips.
    if (metadata.format === 'bmp') {
        try {
           await instance.clone().resize(8, 8).toBuffer();
        } catch (e) {
           throw new Error('Libvips failed to render BMP pixel data');
        }
    }

    return instance.rotate().toColorspace('srgb');
  } catch (error) {
    // 2. Fallback: only strictly necessary for actual legacy/unsupported BMPs
    if (ext === '.bmp') {
      console.log(`Standard Sharp load failed for BMP-like file (${error.message}), switching to bmp-js fallback for: ${filePath}`);
      try {
        const buffer = fs.readFileSync(filePath);
        const bitmap = bmp.decode(buffer);

        // bmp-js returns data in ABGR format [A, B, G, R]
        // Sharp raw input expects RGBA format [R, G, B, A]
        const abgr = bitmap.data;
        const len = abgr.length;
        const rgba = Buffer.alloc(len);

        for (let i = 0; i < len; i += 4) {
          rgba[i]     = abgr[i + 3]; // R
          rgba[i + 1] = abgr[i + 2]; // G
          rgba[i + 2] = abgr[i + 1]; // B

          // CRITICAL FIX FOR INPUT:
          // Instead of copying A (abgr[i]), we FORCE opacity (255).
          // Many "24-bit" BMPs are saved as 32-bit XRGB where X is 0.
          // If we copy '0', the image becomes transparent (invisible).
          rgba[i + 3] = 255; 
        }

        return sharp(rgba, {
          raw: {
            width: bitmap.width,
            height: bitmap.height,
            channels: 4
          }
        }).toColorspace('srgb');

      } catch (bmpError) {
        console.error('bmp-js fallback also failed:', bmpError);
        throw error; 
      }
    }
    throw error;
  }
}

// Routes
app.post('/api/upload', upload.single('image'), async (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  console.log(`Processing upload: ${req.file.originalname} (${req.file.size} bytes)`);

  try {
    const imagePipeline = await getSharpInstance(req.file.path);
    const metadata = await imagePipeline.metadata();

    res.json({
      id: path.parse(req.file.filename).name,
      filename: req.file.filename,
      url: `/api/uploads/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: metadata.width,
      height: metadata.height,
      format: metadata.format,
      depth: metadata.depth
    });
  } catch (error) {
    console.error('Metadata extraction completely failed:', error.message);
    res.json({
      id: path.parse(req.file.filename).name,
      filename: req.file.filename,
      url: `/api/uploads/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: 0, 
      height: 0
    });
  }
});

app.post('/api/process', async (req, res) => {
  const { id, options } = req.body;

  if (!id || !options) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const files = fs.readdirSync(UPLOAD_DIR);
  const originalFile = files.find(f => f.startsWith(id));

  if (!originalFile) {
    return res.status(404).json({ error: 'File not found or expired' });
  }

  const inputPath = path.join(UPLOAD_DIR, originalFile);

  let format = options.format;
  if (format === 'original') {
    format = path.extname(originalFile).slice(1).toLowerCase();
  }
  if (format === 'jpg') format = 'jpeg';

  const outputFilename = `tuku_${id}_${Date.now()}.${format}`;
  const outputPath = path.join(PROCESSED_DIR, outputFilename);

  console.log(`Processing image ${id} -> ${format}`);

  try {
    const instance = await getSharpInstance(inputPath);
    const metadata = await instance.metadata();
    const is16Bit = metadata.depth === 'ushort' || metadata.depth === 'short';

    let pipeline = instance.clone();

    // SAFETY FIX: 
    // If the input is BMP, we force remove alpha channel immediately.
    // Even if we fixed the bmp-js loader, libvips might have loaded a 32-bit BMP (XRGB) as RGBA(0).
    // Removing alpha forces it to ignore the transparency channel and keep pixel values.
    // We DO NOT do this for PNG/WebP, as users might want to preserve transparency there.
    if (metadata.format === 'bmp' || path.extname(originalFile).toLowerCase() === '.bmp') {
        pipeline = pipeline.removeAlpha();
    }

    let currentWidth = metadata.width;
    let currentHeight = metadata.height;

    // 1. Resize
    if ((options.width && options.width > 0) || (options.height && options.height > 0)) {
      if (options.width && options.height) {
         currentWidth = options.width;
         currentHeight = options.height;
      } else if (options.width) {
         currentWidth = options.width;
         if (options.maintainAspectRatio) {
            currentHeight = Math.round(metadata.height * (options.width / metadata.width));
         }
      } else if (options.height) {
         currentHeight = options.height;
         if (options.maintainAspectRatio) {
             currentWidth = Math.round(metadata.width * (options.height / metadata.height));
         }
      }

      pipeline = pipeline.resize({
        width: options.width || null,
        height: options.height || null,
        fit: options.maintainAspectRatio ? (options.resizeMode || 'cover') : 'fill'
      });
    }

    // 2. Rotate & Flip
    if (options.rotate) {
        pipeline = pipeline.rotate(options.rotate);
        if (Math.abs(options.rotate) === 90 || Math.abs(options.rotate) === 270) {
            [currentWidth, currentHeight] = [currentHeight, currentWidth];
        }
    }
    if (options.flipX) pipeline = pipeline.flop();
    if (options.flipY) pipeline = pipeline.flip();

    // 3. Filters
    if (options.grayscale) pipeline = pipeline.grayscale();
    if (options.blur > 0) pipeline = pipeline.blur(0.3 + options.blur);
    if (options.sharpen) pipeline = pipeline.sharpen();

    // 4. Watermark
    if (options.watermarkText) {
       const svgWidth = currentWidth;
       const svgHeight = currentHeight;
       const fontSize = Math.max(Math.floor(svgWidth * 0.05), 20);

       const svgText = `
        <svg width="${svgWidth}" height="${svgHeight}">
          <style>
            .title { 
              fill: rgba(255, 255, 255, 0.5); 
              font-size: ${fontSize}px; 
              font-weight: bold; 
              font-family: 'Noto Sans CJK SC', 'Microsoft YaHei', 'WenQuanYi Micro Hei', sans-serif; 
            }
          </style>
          <text x="50%" y="50%" text-anchor="middle" dominant-baseline="middle" class="title">${options.watermarkText}</text>
        </svg>`;

       pipeline = pipeline.composite([{
          input: Buffer.from(svgText),
          gravity: 'center'
       }]);
    }

    // 5. Output Generation
    if (format === 'bmp') {
        const { data: buffer, info } = await pipeline
          .ensureAlpha() // Add opaque alpha back if it was removed
          .toColorspace('srgb')
          .raw()
          .toBuffer({ resolveWithObject: true });

        const abgrBuffer = Buffer.alloc(buffer.length);
        for (let i = 0; i < buffer.length; i += 4) {
          abgrBuffer[i]     = 255;             // Force Opaque Output
          abgrBuffer[i + 1] = buffer[i + 2];   // B
          abgrBuffer[i + 2] = buffer[i + 1];   // G
          abgrBuffer[i + 3] = buffer[i];       // R
        }

        const rawData = {
          data: abgrBuffer,
          width: info.width,
          height: info.height
        };
        const bmpData = bmp.encode(rawData);
        fs.writeFileSync(outputPath, bmpData.data);

    } else {
        if (['jpeg', 'jpg'].includes(format)) {
             pipeline = pipeline.flatten({ background: '#ffffff' });
             pipeline = pipeline.jpeg({ quality: options.quality });
        } else if (format === 'png') {
            const pngOptions = {};
            if (is16Bit) {
                pngOptions.bitdepth = 16;
                pngOptions.palette = false;
            }
            pipeline = pipeline.png(pngOptions);
        } else if (format === 'webp') {
            pipeline = pipeline.webp({ quality: options.quality });
        } else if (format === 'avif') {
            pipeline = pipeline.avif({ quality: options.quality });
        } else {
            pipeline = pipeline.toFormat(format);
        }

        await pipeline.toFile(outputPath);
    }

    const stats = fs.statSync(outputPath);
    console.log(`Processing complete: ${outputFilename}`);

    res.json({
      url: `/api/processed/${outputFilename}`,
      filename: outputFilename,
      size: stats.size
    });

  } catch (error) {
    console.error('Processing error details:', error);
    const msg = error.message.includes('unsupported image format') 
      ? 'Input format corrupted or unsupported.' 
      : error.message;

    res.status(500).json({ error: `Processing failed: ${msg}` });
  }
});

// Global Error Handler
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === 'LIMIT_FILE_SIZE') {
      return res.status(400).json({ error: 'File too large (Max 20MB)' });
    }
  }
  console.error('Unhandled server error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

import React, { useState } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: ''
};

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);

  // Localization Dictionary for App.tsx
  const t = {
    en: {
      appTitle: "TuKuKu",
      sloganTitle: "Edit & Convert Images Instantly",
      sloganDesc: "Drag and drop your images to start converting, resizing, and optimizing.",
      uploadFailed: "Upload failed",
      processFailed: "Processing failed",
      processedSuccess: "Processed Successfully",
      preview: "Preview",
      originalSize: "Original Size",
      newSize: "New Size",
      savings: "Savings",
      startOver: "Start Over",
      download: "Download",
      serverDesc: "Fast, secure image processing on your server"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "即刻编辑与转换您的图片",
      sloganDesc: "拖拽图片至此，即可开始转换、裁剪与优化。",
      uploadFailed: "上传失败",
      processFailed: "处理失败",
      processedSuccess: "处理成功",
      preview: "预览",
      originalSize: "原始大小",
      newSize: "处理后大小",
      savings: "体积减少",
      startOver: "重新开始",
      download: "下载图片",
      serverDesc: "快速、安全的服务器端图片处理"
    }
  }[lang];

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      // If uploading BMP, we can now set format to BMP (but user is warned it outputs PNG)
      // or just keep it ORIGINAL which the backend also handles safely now.
      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();
      setResult(data);
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    // Hide '8-bit' (uchar) as it's the standard format. 
    // Only show if it's high bit-depth to avoid UI clutter and confusion.
    if (depth === 'uchar') return null; 

    if (depth === 'ushort' || depth === 'short') return '16-bit';
    if (depth === 'float') return '32-bit Float';
    if (depth === 'uint' || depth === 'int') return '32-bit Int';

    // Fallback: capitalize first letter
    return depth.charAt(0).toUpperCase() + depth.slice(1);
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 py-3 px-6 shadow-sm z-10">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-2" onClick={handleReset} role="button">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5 text-white">
                 <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z" />
               </svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">{t.appTitle}</h1>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden md:block text-sm text-slate-500">
               {t.serverDesc}
             </div>
             <button 
               onClick={toggleLang}
               className="flex items-center justify-center px-3 py-1.5 text-xs font-semibold rounded border border-slate-300 hover:bg-slate-50 hover:border-indigo-300 hover:text-indigo-600 transition-colors"
             >
                <svg className="w-4 h-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" />
                </svg>
                {lang === 'en' ? '中文' : 'English'}
             </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden bg-slate-50 relative">
        <div className="absolute inset-0 overflow-y-auto">
          <div className="max-w-7xl mx-auto p-6 h-full min-h-[calc(100vh-64px)]">

            {!currentFile ? (
              <div className="h-full flex flex-col justify-center items-center max-w-2xl mx-auto">
                <div className="w-full text-center mb-10">
                   <h2 className="text-4xl font-extrabold text-slate-800 mb-4">{t.sloganTitle}</h2>
                   <p className="text-lg text-slate-600">{t.sloganDesc}</p>
                </div>
                <Dropzone onFileSelect={handleFileUpload} isUploading={isUploading} lang={lang} />
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-full pb-10">
                {/* Left: Controls */}
                <div className="lg:col-span-1 h-full max-h-[800px]">
                  <Controls 
                    options={options} 
                    setOptions={setOptions} 
                    onProcess={handleProcess}
                    isProcessing={isProcessing}
                    originalDimensions={{ width: currentFile.width || 0, height: currentFile.height || 0 }}
                    lang={lang}
                  />
                </div>

                {/* Right: Preview & Result */}
                <div className="lg:col-span-2 flex flex-col gap-6">
                  {/* Preview Area */}
                  <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm flex-1 flex flex-col items-center justify-center relative overflow-hidden min-h-[400px]">
                    <div className="absolute inset-0" style={{
                      backgroundImage: 'linear-gradient(45deg, #f1f5f9 25%, transparent 25%), linear-gradient(-45deg, #f1f5f9 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #f1f5f9 75%), linear-gradient(-45deg, transparent 75%, #f1f5f9 75%)',
                      backgroundSize: '20px 20px',
                      backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px'
                    }}></div>

                    <div className="relative z-10 max-w-full max-h-full p-4 flex items-center justify-center w-full h-full">
                      {result ? (
                         <div className="flex flex-col items-center">
                            <img 
                              src={result.url} 
                              alt="Processed" 
                              decoding="async"
                              className="max-h-[500px] object-contain shadow-xl rounded-lg border border-slate-300" 
                            />
                            <div className="mt-4 bg-green-50 text-green-700 px-4 py-2 rounded-full text-sm font-medium border border-green-200 flex items-center">
                               <svg className="w-4 h-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                               {t.processedSuccess}
                            </div>
                         </div>
                      ) : (
                        <div className="relative group flex items-center justify-center w-full h-full">
                           {/* Added transform-gpu, will-change-transform, and decoding=async to improve performance and prevent lag */}
                           <img 
                             src={currentFile.url} 
                             alt="Original" 
                             decoding="async"
                             loading="lazy"
                             className="max-h-[500px] object-contain shadow-xl rounded-lg border border-slate-300 transition-transform duration-300 transform-gpu will-change-transform" 
                             style={{
                               transform: `rotate(${options.rotate}deg) scaleX(${options.flipX ? -1 : 1}) scaleY(${options.flipY ? -1 : 1})`,
                               filter: `
                                 grayscale(${options.grayscale ? 1 : 0}) 
                                 blur(${options.blur}px)
                                 ${options.sharpen ? 'contrast(1.2)' : ''}
                               `
                             }} 
                           />
                           {!result && <div className="absolute top-2 right-2 bg-black/60 text-white text-xs px-2 py-1 rounded backdrop-blur-sm">{t.preview}</div>}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Actions Bar */}
                  {result && (
                    <div className="bg-white border border-slate-200 p-4 rounded-xl shadow-sm flex items-center justify-between animate-fade-in-up">
                       <div className="flex items-center gap-4">
                          <div className="text-sm">
                             <p className="text-slate-500">{t.originalSize}</p>
                             <p className="font-semibold text-slate-800">
                               {formatSize(currentFile.size)} 
                               {getBitDepthLabel(currentFile.depth) && (
                                 <>
                                   <span className="text-slate-300 mx-2">|</span> 
                                   {getBitDepthLabel(currentFile.depth)}
                                 </>
                               )}
                             </p>
                          </div>
                          <div className="w-px h-8 bg-slate-200"></div>
                          <div className="text-sm">
                             <p className="text-slate-500">{t.newSize}</p>
                             <p className="font-semibold text-indigo-600">{formatSize(result.size)}</p>
                          </div>
                          <div className="w-px h-8 bg-slate-200"></div>
                          <div className="text-sm">
                             <p className="text-slate-500">{t.savings}</p>
                             <p className="font-semibold text-green-600">
                               {currentFile.size > result.size 
                                 ? Math.round(((currentFile.size - result.size) / currentFile.size) * 100) + '%'
                                 : '-'}
                             </p>
                          </div>
                       </div>

                       <div className="flex gap-3">
                         <button 
                           onClick={handleReset}
                           className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition-colors"
                         >
                           {t.startOver}
                         </button>
                         <a 
                           href={result.url} 
                           download={result.filename}
                           className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-2 rounded-lg font-semibold hover:bg-indigo-700 hover:shadow-lg hover:shadow-indigo-500/30 transition-all active:scale-95"
                         >
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                            {t.download}
                         </a>
                       </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

