    } else {
        const KNOWN_RESOLUTIONS = {
            5898240: [1920, 1536], 
            4147200: [1920, 1080], 
            1843200: [1280, 720], 
            614400:  [640, 480],   
        };
        const dims = KNOWN_RESOLUTIONS[size];
        if (dims) {
