            console.log(`Guessed resolution from size ${size}: ${width}x${height}`);
        }
    }

    if (width && height) {
      const buffer = fs.readFileSync(filePath);
      let rgbaBuffer;

      switch (pixelFormat.toLowerCase()) {
          case 'uyvy':
              rgbaBuffer = uyvyToRgba(buffer, width, height);
              break;
          case 'yuy2':
              rgbaBuffer = yuy2ToRgba(buffer, width, height);
              break;
          case 'nv21':
              rgbaBuffer = nv21ToRgba(buffer, width, height);
              break;
          case 'rgba':
              rgbaBuffer = buffer; 
              break;
          case 'rgb':
              return sharp(buffer, {
                  raw: { width, height, channels: 3 }
              }).toColorspace('srgb');
          default:
              console.warn(`Unknown pixel format ${pixelFormat}, defaulting to UYVY`);
              rgbaBuffer = uyvyToRgba(buffer, width, height);
              break;
      }

      return sharp(rgbaBuffer, {
        raw: {
          width: width,
          height: height,
          channels: 4
        }
      }).toColorspace('srgb');
    }
  }

  // --- BMP Handling Override ---
  // We force manual decoding for BMP to avoid Sharp/libvips channel swapping or stride issues
  if (ext === '.bmp') {
    try {
      console.log("Forcing manual decode for BMP: " + filePath);
      const buffer = fs.readFileSync(filePath);
      const bitmap = bmp.decode(buffer);
      const rawData = bitmap.data; // bmp-js returns ABGR (Alpha, Blue, Green, Red) sequence
      const len = rawData.length;
      const rgba = Buffer.alloc(len);

