    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      <div className="p-4 border-b border-slate-100 bg-slate-50">
        <h2 className="font-semibold text-slate-800 flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5 mr-2 text-indigo-600">
            <path d="M10 3.75a2 2 0 10-4 0 2 2 0 004 0zM17.25 4.5a.75.75 0 00-1.5 0h-2.5a.75.75 0 000 1.5h2.5a.75.75 0 001.5 0zm-14.5 0a.75.75 0 000 1.5h2.5a.75.75 0 000-1.5h-2.5zM10 8.5a2 2 0 10-4 0 2 2 0 004 0zM17.25 9.25a.75.75 0 00-1.5 0h-2.5a.75.75 0 000 1.5h2.5a.75.75 0 001.5 0zm-14.5 0a.75.75 0 000 1.5h2.5a.75.75 0 000-1.5h-2.5zM10 13.25a2 2 0 10-4 0 2 2 0 004 0zM17.25 14a.75.75 0 00-1.5 0h-2.5a.75.75 0 000 1.5h2.5a.75.75 0 001.5 0zm-14.5 0a.75.75 0 000 1.5h2.5a.75.75 0 000-1.5h-2.5z" />
          </svg>
          {t.settings}
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">

        {/* RAW Format Specific Settings - Shown ONLY for Raw files */}
        {isRaw && (
          <section className="bg-amber-50 p-3 rounded-lg border border-amber-200 shadow-sm">
             <label className="block text-sm font-bold text-amber-800 mb-1">{t.sourceSettings}</label>
             <p className="text-xs text-amber-700 mb-3">{t.sourceDesc}</p>

             {/* Pixel Format Selector */}
             <div className="mb-3">
               <label className="block text-xs font-semibold text-amber-800 mb-1">{t.pixelFormat}</label>
               <select
                 value={options.rawPixelFormat || 'uyvy'}
                 onChange={(e) => updateOption('rawPixelFormat', e.target.value as RawPixelFormat)}
                 className="w-full px-2 py-1.5 text-sm border border-amber-300 rounded-md focus:ring-amber-500 focus:border-amber-500 bg-white"
               >
                 <option value="uyvy">UYVY (YUV 4:2:2)</option>
                 <option value="nv21">NV21 (YUV 4:2:0)</option>
                 <option value="rgba">RGBA (32-bit)</option>
                 <option value="bgra">BGRA (32-bit)</option>
                 <option value="rgb">RGB (24-bit)</option>
                 <option value="bgr">BGR (24-bit)</option>
               </select>
             </div>

             <div className="flex gap-2 items-center">
                <div className="relative w-full">
                  <input
                    type="number"
                    placeholder="W"
                    value={options.rawWidth || ''}
                    onChange={(e) => updateOption('rawWidth', e.target.value ? Number(e.target.value) : undefined)}
                    className="w-full pl-3 pr-8 py-2 text-sm border border-amber-300 rounded-md focus:ring-amber-500 focus:border-amber-500 bg-white"
                  />
                  <span className="absolute right-3 top-2 text-xs text-slate-400">px</span>
                </div>
                <span className="text-slate-400">×</span>
                <div className="relative w-full">
                  <input
                    type="number"
                    placeholder="H"
                    value={options.rawHeight || ''}
                    onChange={(e) => updateOption('rawHeight', e.target.value ? Number(e.target.value) : undefined)}
                    className="w-full pl-3 pr-8 py-2 text-sm border border-amber-300 rounded-md focus:ring-amber-500 focus:border-amber-500 bg-white"
                  />
                  <span className="absolute right-3 top-2 text-xs text-slate-400">px</span>
                </div>
              </div>
          </section>
        )}

        {/* Format & Quality */}
        <section>
          <label className="block text-sm font-medium text-slate-700 mb-2">{t.format}</label>
          <div className="grid grid-cols-3 gap-2">
            {[ImageFormat.ORIGINAL, ImageFormat.JPEG, ImageFormat.PNG, ImageFormat.WEBP, ImageFormat.BMP].map(fmt => (
              <button
                key={fmt}
                onClick={() => updateOption('format', fmt)}
                className={`px-3 py-2 text-sm rounded-md border uppercase ${
                  options.format === fmt 
                    ? 'bg-indigo-600 text-white border-indigo-600' 
                    : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'
                }`}
              >
                {fmt === 'original' ? 'ORIG' : fmt}
              </button>
            ))}
          </div>
        </section>

        {options.format !== ImageFormat.PNG && options.format !== ImageFormat.BMP && (
          <section>
            <div className="flex justify-between mb-2">
              <label className="text-sm font-medium text-slate-700">{t.quality}</label>
              <span className="text-sm text-slate-500">{options.quality}%</span>
            </div>
            <input
              type="range"
              min="10"
              max="100"
              value={options.quality}
              onChange={(e) => updateOption('quality', Number(e.target.value))}
              className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
            />
          </section>
        )}

        {/* Dimensions */}
        <section>
          <label className="block text-sm font-medium text-slate-700 mb-2">{t.resize}</label>
          <div className="flex gap-2 items-center mb-3">
            <div className="relative w-full">
              <input
                type="number"
                placeholder={originalDimensions?.width ? originalDimensions.width.toString() : 'Width'}
                value={options.width || ''}
                onChange={(e) => updateOption('width', e.target.value ? Number(e.target.value) : null)}
                className="w-full pl-3 pr-8 py-2 text-sm border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              />
              <span className="absolute right-3 top-2 text-xs text-slate-400">px</span>
            </div>
            <span className="text-slate-400">×</span>
            <div className="relative w-full">
              <input
                type="number"
                placeholder={originalDimensions?.height ? originalDimensions.height.toString() : 'Height'}
                value={options.height || ''}
                onChange={(e) => updateOption('height', e.target.value ? Number(e.target.value) : null)}
                className="w-full pl-3 pr-8 py-2 text-sm border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              />
              <span className="absolute right-3 top-2 text-xs text-slate-400">px</span>
            </div>
          </div>
          <div className="flex items-center">
            <input
              type="checkbox"
              id="aspect"
              checked={options.maintainAspectRatio}
              onChange={(e) => updateOption('maintainAspectRatio', e.target.checked)}
              className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
            />
            <label htmlFor="aspect" className="ml-2 text-sm text-slate-600">{t.maintainAspect}</label>
          </div>
        </section>

        {/* Adjustments */}
        <section>
          <label className="block text-sm font-medium text-slate-700 mb-2">{t.transform}</label>
          <div className="flex gap-2 mb-3">
             <button 
               onClick={() => updateOption('rotate', (options.rotate - 90) % 360)}
               className="flex-1 py-2 border border-slate-300 rounded-md text-sm hover:bg-slate-50 text-slate-700"
             >
               ↺ -90°
             </button>
             <button 
               onClick={() => updateOption('rotate', (options.rotate + 90) % 360)}
               className="flex-1 py-2 border border-slate-300 rounded-md text-sm hover:bg-slate-50 text-slate-700"
             >
               ↻ +90°
             </button>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => updateOption('flipX', !options.flipX)}
              className={`flex-1 py-2 border rounded-md text-sm ${options.flipX ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}
            >
              Flip H
            </button>
            <button 
              onClick={() => updateOption('flipY', !options.flipY)}
              className={`flex-1 py-2 border rounded-md text-sm ${options.flipY ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}
            >
              Flip V
            </button>
          </div>
        </section>

        {/* Filters */}
        <section>
           <label className="block text-sm font-medium text-slate-700 mb-2">{t.filters}</label>
           <div className="space-y-3">
             <div className="flex items-center justify-between">
                <span className="text-sm text-slate-600">{t.grayscale}</span>
                <input 
                  type="checkbox" 
                  checked={options.grayscale}
                  onChange={(e) => updateOption('grayscale', e.target.checked)}
                  className="toggle-checkbox h-5 w-5 text-indigo-600 rounded focus:ring-indigo-500"
                />
             </div>
             <div className="flex items-center justify-between">
                <span className="text-sm text-slate-600">{t.sharpen}</span>
                <input 
                  type="checkbox" 
                  checked={options.sharpen}
                  onChange={(e) => updateOption('sharpen', e.target.checked)}
                  className="toggle-checkbox h-5 w-5 text-indigo-600 rounded focus:ring-indigo-500"
                />
             </div>
             <div>
                <div className="flex justify-between mb-1">
                  <span className="text-sm text-slate-600">{t.blur}</span>
                  <span className="text-xs text-slate-400">{options.blur}px</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="20"
                  step="0.5"
                  value={options.blur}
                  onChange={(e) => updateOption('blur', Number(e.target.value))}
                  className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                />
             </div>
           </div>
        </section>

        {/* Watermark */}
        <section>
           <label className="block text-sm font-medium text-slate-700 mb-2">{t.watermark}</label>
           <input
             type="text"
             placeholder={t.watermarkPlaceholder}
             value={options.watermarkText}
             onChange={(e) => updateOption('watermarkText', e.target.value)}
             className="w-full px-3 py-2 text-sm border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
           />
        </section>
      </div>

      <div className="p-4 border-t border-slate-100 bg-slate-50">
        <button
          onClick={onProcess}
          disabled={isProcessing}
          className={`w-full py-3 px-4 rounded-lg font-semibold text-white shadow-lg transition-all
            ${isProcessing 
              ? 'bg-indigo-400 cursor-not-allowed' 
              : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-500/30 active:scale-[0.98]'
            }
          `}
        >
          {isProcessing ? t.processing : t.processBtn}
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language, RawPixelFormat } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: '',
  rawWidth: undefined,
  rawHeight: undefined,
  rawPixelFormat: 'uyvy' // default
};

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);

  // Localization Dictionary for App.tsx
  const t = {
    en: {
      appTitle: "TuKuKu",
      sloganTitle: "Edit & Convert Images Instantly",
      sloganDesc: "Drag and drop your images to start converting, resizing, and optimizing.",
      uploadFailed: "Upload failed",
      processFailed: "Processing failed",
      processedSuccess: "Processed Successfully",
      preview: "Preview",
      noPreview: "Preview not available for RAW formats",
      originalSize: "Original Size",
      newSize: "New Size",
      savings: "Savings",
      startOver: "Start Over",
      download: "Download",
      serverDesc: "Fast, secure image processing on your server"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "即刻编辑与转换您的图片",
      sloganDesc: "拖拽图片至此，即可开始转换、裁剪与优化。",
      uploadFailed: "上传失败",
      processFailed: "处理失败",
      processedSuccess: "处理成功",
      preview: "预览",
      noPreview: "RAW 格式暂不支持预览",
      originalSize: "原始大小",
      newSize: "处理后大小",
      savings: "体积减少",
      startOver: "重新开始",
      download: "下载图片",
      serverDesc: "快速、安全的服务器端图片处理"
    }
  }[lang];

  // Helper to guess pixel format from extension
  const getFormatFromExt = (filename: string): RawPixelFormat => {
      const lower = filename.toLowerCase();
      if (lower.endsWith('.uyvy')) return 'uyvy';
      if (lower.endsWith('.nv21')) return 'nv21';
      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; // default fallback
  };

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      const suggestedFormat = getFormatFromExt(data.originalName);

      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null,
        // If the backend managed to guess dimensions (e.g. from file size map), pre-fill them
        // If not (width=0), leave them undefined to prompt user
        rawWidth: data.width || 1920,
        rawHeight: data.height || 1080,
        rawPixelFormat: suggestedFormat
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();
      setResult(data);
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    if (depth === 'uchar') return null; 
    if (depth === 'ushort' || depth === 'short') return '16-bit';
    if (depth === 'float') return '32-bit Float';
    if (depth === 'uint' || depth === 'int') return '32-bit Int';
    return depth.charAt(0).toUpperCase() + depth.slice(1);
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  // Helper to check for raw formats that browser can't render
  const isRawFormat = (filename: string) => {
      const exts = ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'];
      return exts.some(ext => filename.toLowerCase().endsWith(ext));
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 py-3 px-6 shadow-sm z-10">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-2" onClick={handleReset} role="button">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5 text-white">
                 <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z" />
               </svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">{t.appTitle}</h1>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden md:block text-sm text-slate-500">
               {t.serverDesc}
             </div>
             <button 
               onClick={toggleLang}
               className="flex items-center justify-center px-3 py-1.5 text-xs font-semibold rounded border border-slate-300 hover:bg-slate-50 hover:border-indigo-300 hover:text-indigo-600 transition-colors"
             >
                <svg className="w-4 h-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" />
                </svg>
                {lang === 'en' ? '中文' : 'English'}
             </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden bg-slate-50 relative">
        <div className="absolute inset-0 overflow-y-auto">
          <div className="max-w-7xl mx-auto p-6 h-full min-h-[calc(100vh-64px)]">

            {!currentFile ? (
              <div className="h-full flex flex-col justify-center items-center max-w-2xl mx-auto">
                <div className="w-full text-center mb-10">
                   <h2 className="text-4xl font-extrabold text-slate-800 mb-4">{t.sloganTitle}</h2>
                   <p className="text-lg text-slate-600">{t.sloganDesc}</p>
                </div>
                <Dropzone onFileSelect={handleFileUpload} isUploading={isUploading} lang={lang} />
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-full pb-10">
                {/* Left: Controls */}
                <div className="lg:col-span-1 h-full max-h-[800px]">
                  <Controls 
                    options={options} 
                    setOptions={setOptions} 
                    onProcess={handleProcess}
                    isProcessing={isProcessing}
                    originalDimensions={{ width: currentFile.width || 0, height: currentFile.height || 0 }}
                    lang={lang}
                    inputFormat={currentFile.originalName} 
                  />
                </div>

                {/* Right: Preview & Result */}
                <div className="lg:col-span-2 flex flex-col gap-6">
                  {/* Preview Area */}
                  <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm flex-1 flex flex-col items-center justify-center relative overflow-hidden min-h-[400px]">
                    <div className="absolute inset-0" style={{
                      backgroundImage: 'linear-gradient(45deg, #f1f5f9 25%, transparent 25%), linear-gradient(-45deg, #f1f5f9 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #f1f5f9 75%), linear-gradient(-45deg, transparent 75%, #f1f5f9 75%)',
                      backgroundSize: '20px 20px',
                      backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px'
                    }}></div>

                    <div className="relative z-10 max-w-full max-h-full p-4 flex items-center justify-center w-full h-full">
                      {result ? (
                         <div className="flex flex-col items-center">
                            <img 
                              src={result.url} 
                              alt="Processed" 
                              decoding="async"
                              className="max-h-[500px] object-contain shadow-xl rounded-lg border border-slate-300" 
                            />
                            <div className="mt-4 bg-green-50 text-green-700 px-4 py-2 rounded-full text-sm font-medium border border-green-200 flex items-center">
                               <svg className="w-4 h-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                               {t.processedSuccess}
                            </div>
                         </div>
                      ) : (
                        <div className="relative group flex items-center justify-center w-full h-full">
                           {isRawFormat(currentFile.filename) ? (
                              <div className="flex flex-col items-center justify-center p-8 bg-white/80 rounded-lg shadow-sm border border-slate-200 backdrop-blur-sm">
                                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-12 h-12 text-slate-400 mb-2">
                                    <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                                 </svg>
                                 <span className="text-slate-500 font-medium">{t.noPreview}</span>
                                 <span className="text-slate-400 text-sm mt-1 text-center max-w-xs">
                                    {lang === 'en' ? 'Check RAW Settings.' : '请检查 Raw 数据设置。'}
                                 </span>
                              </div>
                           ) : (
                             <>
                               <img 
                                 src={currentFile.url} 
                                 alt="Original" 
                                 decoding="async"
