                               />
                               <div className="absolute top-4 right-4 bg-black/70 border border-cyan-500/30 text-cyan-400 text-[10px] font-code px-3 py-1 backdrop-blur-md uppercase tracking-widest z-20">
                                 ● {t.preview}
                               </div>
                             </>
