      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; 
