      depth: metadata.depth
    });
  } catch (error) {
    console.error('Metadata extraction failed:', error.message);
    res.json({
      id: path.parse(req.file.filename).name,
      filename: req.file.filename,
      url: `/api/uploads/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: 0, 
      height: 0
    });
  }
});

app.post('/api/process', async (req, res) => {
  const { id, options } = req.body;

  if (!id || !options) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const files = fs.readdirSync(UPLOAD_DIR);
  const originalFile = files.find(f => f.startsWith(id));

  if (!originalFile) {
    return res.status(404).json({ error: 'File not found or expired' });
  }

  const inputPath = path.join(UPLOAD_DIR, originalFile);

  let format = options.format;
  if (format === 'original') {
    format = path.extname(originalFile).slice(1).toLowerCase();
    // Map raw extensions to default png output
    if (['uyvy', 'yuv', 'nv21', 'rgb', 'raw', 'bin', 'bgra', 'rgba'].includes(format)) format = 'png';
  }
  if (format === 'jpg') format = 'jpeg';
  if (['uyvy', 'yuv', 'nv21', 'rgb', 'raw', 'bin', 'bgra', 'rgba'].includes(format)) format = 'png';

  const outputFilename = `tuku_${id}_${Date.now()}.${format}`;
  const outputPath = path.join(PROCESSED_DIR, outputFilename);

  console.log(`Processing image ${id} -> ${format}`);

  try {
    const rawOptions = {
        width: options.rawWidth,
        height: options.rawHeight,
        pixelFormat: options.rawPixelFormat
    };

    const instance = await getSharpInstance(inputPath, rawOptions);
    const metadata = await instance.metadata();

    let pipeline = instance.clone();
    pipeline = pipeline.ensureAlpha(); 

    let currentWidth = metadata.width;
    let currentHeight = metadata.height;

    // 1. Resize
    if ((options.width && options.width > 0) || (options.height && options.height > 0)) {
      if (options.width && options.height) {
         currentWidth = options.width;
         currentHeight = options.height;
      } else if (options.width) {
         currentWidth = options.width;
         if (options.maintainAspectRatio) {
            currentHeight = Math.round(metadata.height * (options.width / metadata.width));
         }
      } else if (options.height) {
         currentHeight = options.height;
         if (options.maintainAspectRatio) {
             currentWidth = Math.round(metadata.width * (options.height / metadata.height));
         }
      }

      pipeline = pipeline.resize({
        width: options.width || null,
        height: options.height || null,
        fit: options.maintainAspectRatio ? (options.resizeMode || 'cover') : 'fill'
      });
    }

    // 2. Rotate & Flip
    if (options.rotate) {
        pipeline = pipeline.rotate(options.rotate);
        if (Math.abs(options.rotate) === 90 || Math.abs(options.rotate) === 270) {
            [currentWidth, currentHeight] = [currentHeight, currentWidth];
        }
    }
    if (options.flipX) pipeline = pipeline.flop();
    if (options.flipY) pipeline = pipeline.flip();

    // 3. Filters
    if (options.grayscale) pipeline = pipeline.grayscale();
    if (options.blur > 0) pipeline = pipeline.blur(0.3 + options.blur);
    if (options.sharpen) pipeline = pipeline.sharpen();

    // 4. Watermark
    if (options.watermarkText) {
       const svgWidth = currentWidth;
       const svgHeight = currentHeight;
       const fontSize = Math.max(Math.floor(svgWidth * 0.03), 20); // Scale with image, min 20px
       const lineHeight = fontSize * 1.2;
       const padding = fontSize; 

       const escapeXml = (unsafe) => {
          return unsafe.replace(/[<>&'"]/g, (c) => {
            switch (c) {
              case '<': return '&lt;';
              case '>': return '&gt;';
              case '&': return '&amp;';
              case '\'': return '&apos;';
              case '"': return '&quot;';
            }
          });
       };

       const lines = options.watermarkText.split(/\r?\n/);

       // Calculate position for BOTTOM-RIGHT
       // We use text-anchor="end", so the X coordinate is the right boundary (width - padding).
       // We start drawing from the top line, so we need to calculate the Y of the first line
       // such that the last line lands at (height - padding).
       const startX = svgWidth - padding; 
       const startY = svgHeight - padding - ((lines.length - 1) * lineHeight);

       const tspans = lines.map((line, i) => {
          const safeLine = escapeXml(line);
          const dy = i === 0 ? 0 : lineHeight;
          // For multi-line with 'end' anchor, repeating 'x' is safe/required to keep alignment
          return `<tspan x="${startX}" dy="${dy}">${safeLine}</tspan>`;
       }).join('');

       const svgText = `
        <svg width="${svgWidth}" height="${svgHeight}">
          <style>
            .watermark { 
              fill: rgba(255, 255, 255, 0.85); 
              font-size: ${fontSize}px; 
              font-weight: bold; 
              font-family: 'Noto Sans CJK SC', 'Microsoft YaHei', sans-serif; 
              text-anchor: end;
              text-shadow: 2px 2px 4px rgba(0,0,0,0.8); 
            }
          </style>
          <text x="${startX}" y="${startY}" class="watermark">${tspans}</text>
        </svg>`;

       pipeline = pipeline.composite([{
          input: Buffer.from(svgText),
          gravity: 'center' 
       }]);
    }

    // 5. Output Generation
    if (format === 'bmp') {
        const { data: buffer, info } = await pipeline
          .toColorspace('srgb')
          .raw()
          .toBuffer({ resolveWithObject: true });

        // Convert RGBA -> ABGR for bmp-js
        const abgrBuffer = Buffer.alloc(buffer.length);
        for (let i = 0; i < buffer.length; i += 4) {
          const r = buffer[i];
          const g = buffer[i + 1];
          const b = buffer[i + 2];
          const a = buffer[i + 3];

          abgrBuffer[i]     = a; 
          abgrBuffer[i + 1] = b; 
          abgrBuffer[i + 2] = g; 
          abgrBuffer[i + 3] = r; 
        }

        const rawData = {
          data: abgrBuffer,
          width: info.width,
          height: info.height
        };
        const bmpData = bmp.encode(rawData);
        fs.writeFileSync(outputPath, bmpData.data);

    } else {
        if (['jpeg', 'jpg'].includes(format)) {
             pipeline = pipeline.flatten({ background: '#ffffff' });
             pipeline = pipeline.jpeg({ quality: options.quality });
        } else if (format === 'png') {
            pipeline = pipeline.png();
        } else if (format === 'webp') {
            pipeline = pipeline.webp({ quality: options.quality });
        } else if (format === 'avif') {
            pipeline = pipeline.avif({ quality: options.quality });
        } else {
            pipeline = pipeline.toFormat(format);
        }

        await pipeline.toFile(outputPath);
    }

    const stats = fs.statSync(outputPath);
    console.log(`Processing complete: ${outputFilename}`);

    res.json({
      url: `/api/processed/${outputFilename}`,
      filename: outputFilename,
      size: stats.size
    });

  } catch (error) {
    console.error('Processing error details:', error);
    const msg = error.message.includes('unsupported image format') 
      ? 'Input format corrupted or unsupported.' 
      : error.message;

    res.status(500).json({ error: `Processing failed: ${msg}` });
  }
});

// Global Error Handler
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === 'LIMIT_FILE_SIZE') {
      return res.status(400).json({ error: 'File too large (Max 20MB)' });
    }
  }
  console.error('Unhandled server error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

import React from 'react';
import { ImageFormat, ProcessOptions, Language, RawPixelFormat } from '../types';

interface ControlsProps {
  options: ProcessOptions;
  setOptions: React.Dispatch<React.SetStateAction<ProcessOptions>>;
  onProcess: () => void;
  isProcessing: boolean;
  originalDimensions?: { width: number; height: number };
  lang: Language;
  inputFormat?: string; // Passed from parent to detect if raw inputs are needed
}

export const Controls: React.FC<ControlsProps> = ({ 
  options, 
  setOptions, 
  onProcess, 
  isProcessing,
  originalDimensions,
  lang,
  inputFormat
}) => {

  const t = {
    en: {
      settings: "SYSTEM_CONFIG",
      sourceSettings: "RAW_DATA_INPUT",
      sourceDesc: "Required: Specify format & dimensions.",
      format: "OUTPUT_FORMAT",
      pixelFormat: "PIXEL_FORMAT",
      quality: "COMPRESSION",
      resize: "DIMENSIONS",
      maintainAspect: "LOCK_ASPECT",
      transform: "TRANSFORM",
      filters: "FILTERS",
      grayscale: "GRAYSCALE",
      sharpen: "SHARPEN",
      blur: "GAUSSIAN_BLUR",
      watermark: "WATERMARK",
      watermarkPlaceholder: "Enter text... (Press Enter for new line)",
      processBtn: "EXECUTE_PROCESS",
      processing: "PROCESSING..."
    },
    zh: {
      settings: "系统配置",
      sourceSettings: "RAW 数据源",
      sourceDesc: "必填：指定格式与尺寸",
      format: "输出格式",
      pixelFormat: "像素格式",
      quality: "压缩质量",
      resize: "尺寸调整",
      maintainAspect: "锁定比例",
      transform: "变换控制",
      filters: "图像滤镜",
      grayscale: "灰度模式",
      sharpen: "锐化增强",
      blur: "高斯模糊",
      watermark: "水印叠加",
      watermarkPlaceholder: "输入文本... (按回车换行)",
      processBtn: "执行处理",
      processing: "处理中..."
    }
  }[lang];

  const updateOption = <K extends keyof ProcessOptions>(key: K, value: ProcessOptions[K]) => {
    setOptions(prev => ({ ...prev, [key]: value }));
  };

  // Helper to handle dimension changes with aspect ratio locking
  const handleDimensionChange = (dimension: 'width' | 'height', value: string) => {
    const numValue = value ? Number(value) : null;

    setOptions(prev => {
      const next = { ...prev, [dimension]: numValue };

      // Auto-calculate the other dimension if aspect ratio is locked and we have original dims
      // Note: originalDimensions.width > 0 check ensures we don't divide by zero or use invalid metadata
      if (
        prev.maintainAspectRatio && 
        originalDimensions && 
        originalDimensions.width > 0 && 
        originalDimensions.height > 0 && 
        numValue !== null
      ) {
        const ratio = originalDimensions.width / originalDimensions.height;

        if (dimension === 'width') {
          next.height = Math.round(numValue / ratio);
        } else {
          next.width = Math.round(numValue * ratio);
        }
      }
      return next;
    });
  };

  // Helper to handle toggling the checkbox
  const handleAspectToggle = (checked: boolean) => {
    setOptions(prev => {
      const next = { ...prev, maintainAspectRatio: checked };
      // If turning ON, and we have a width, sync the height immediately
      if (
        checked && 
        originalDimensions && 
        originalDimensions.width > 0 && 
        originalDimensions.height > 0 && 
        next.width
      ) {
         const ratio = originalDimensions.width / originalDimensions.height;
         next.height = Math.round(next.width / ratio);
      }
      return next;
    });
  };

  const isRaw = inputFormat && (
      ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'].some(ext => inputFormat.toLowerCase().endsWith(ext))
  );

  return (
    <div className="bg-slate-900/80 backdrop-blur-md rounded-none border border-cyan-900/50 flex flex-col h-full overflow-hidden relative">
      {/* Header Accent */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-600 to-transparent"></div>

      <div className="p-4 border-b border-cyan-900/30 bg-slate-900/50 flex justify-between items-center">
        <h2 className="font-tech font-bold text-cyan-400 tracking-wider flex items-center">
          <span className="w-2 h-2 bg-cyan-500 mr-3 animate-pulse"></span>
          {t.settings}
        </h2>
        <div className="flex gap-1">
           <div className="w-1 h-1 bg-slate-600"></div>
           <div className="w-1 h-1 bg-slate-600"></div>
           <div className="w-1 h-1 bg-slate-600"></div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-8 custom-scrollbar">

        {/* RAW Format Specific Settings */}
        {isRaw && (
          <section className="bg-amber-900/20 p-4 border-l-2 border-amber-500">
             <label className="block text-xs font-bold text-amber-500 mb-1 font-tech tracking-wider">{t.sourceSettings}</label>
             <p className="text-[10px] text-amber-400/70 mb-4 font-code">{t.sourceDesc}</p>

             <div className="mb-4">
               <label className="block text-[10px] font-semibold text-slate-400 mb-1 font-code">{t.pixelFormat}</label>
               <select
                 value={options.rawPixelFormat || 'uyvy'}
                 onChange={(e) => updateOption('rawPixelFormat', e.target.value as RawPixelFormat)}
                 className="w-full bg-black/40 border border-amber-500/30 text-amber-100 text-xs py-2 px-3 focus:outline-none focus:border-amber-500 font-code uppercase"
               >
                 <option value="uyvy">UYVY (YUV 4:2:2)</option>
                 <option value="nv21">NV21 (YUV 4:2:0)</option>
                 <option value="rgba">RGBA (32-bit)</option>
                 <option value="bgra">BGRA (32-bit)</option>
                 <option value="rgb">RGB (24-bit)</option>
                 <option value="bgr">BGR (24-bit)</option>
               </select>
             </div>

             <div className="flex gap-2 items-center">
                <div className="relative w-full">
                  <input
                    type="number"
                    placeholder="W"
                    value={options.rawWidth || ''}
                    onChange={(e) => updateOption('rawWidth', e.target.value ? Number(e.target.value) : undefined)}
                    className="w-full bg-black/40 border border-amber-500/30 text-amber-100 text-xs py-2 px-3 pl-3 pr-8 focus:outline-none focus:border-amber-500 font-code"
                  />
                  <span className="absolute right-3 top-2 text-[10px] text-slate-500">px</span>
                </div>
                <span className="text-slate-600">×</span>
                <div className="relative w-full">
                  <input
                    type="number"
                    placeholder="H"
                    value={options.rawHeight || ''}
                    onChange={(e) => updateOption('rawHeight', e.target.value ? Number(e.target.value) : undefined)}
                    className="w-full bg-black/40 border border-amber-500/30 text-amber-100 text-xs py-2 px-3 pl-3 pr-8 focus:outline-none focus:border-amber-500 font-code"
                  />
                  <span className="absolute right-3 top-2 text-[10px] text-slate-500">px</span>
                </div>
              </div>
          </section>
        )}

        {/* Format */}
        <section>
          <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.format}</label>
          <div className="grid grid-cols-3 gap-2">
            {[ImageFormat.ORIGINAL, ImageFormat.JPEG, ImageFormat.PNG, ImageFormat.WEBP, ImageFormat.BMP].map(fmt => (
              <button
                key={fmt}
                onClick={() => updateOption('format', fmt)}
                className={`px-2 py-2 text-[10px] border font-code uppercase transition-all
                  ${options.format === fmt 
                    ? 'bg-cyan-500/20 border-cyan-400 text-cyan-300 shadow-[0_0_10px_rgba(6,182,212,0.2)]' 
                    : 'bg-transparent border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'
                  }`}
              >
                {fmt === 'original' ? 'ORIG' : fmt}
              </button>
            ))}
          </div>
        </section>

        {options.format !== ImageFormat.PNG && options.format !== ImageFormat.BMP && (
          <section>
            <div className="flex justify-between mb-2">
              <label className="text-xs font-bold text-cyan-500 font-tech tracking-wider uppercase">{t.quality}</label>
              <span className="text-xs font-code text-cyan-300">{options.quality}%</span>
            </div>
            <input
              type="range"
              min="10"
              max="100"
              value={options.quality}
              onChange={(e) => updateOption('quality', Number(e.target.value))}
              className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
            />
          </section>
        )}

        {/* Dimensions */}
        <section>
          <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.resize}</label>
          <div className="flex gap-2 items-center mb-3">
            <div className="relative w-full">
              <input
                type="number"
                placeholder={originalDimensions?.width ? originalDimensions.width.toString() : 'Width'}
                value={options.width || ''}
                onChange={(e) => handleDimensionChange('width', e.target.value)}
                className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code placeholder-slate-600"
              />
              <span className="absolute right-3 top-2 text-[10px] text-slate-600">W</span>
            </div>
            <span className="text-slate-600 text-xs">×</span>
            <div className="relative w-full">
              <input
                type="number"
                placeholder={originalDimensions?.height ? originalDimensions.height.toString() : 'Height'}
                value={options.height || ''}
                onChange={(e) => handleDimensionChange('height', e.target.value)}
                className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code placeholder-slate-600"
              />
              <span className="absolute right-3 top-2 text-[10px] text-slate-600">H</span>
            </div>
          </div>
          <div className="flex items-center">
            <input
              type="checkbox"
              id="aspect"
              checked={options.maintainAspectRatio}
              onChange={(e) => handleAspectToggle(e.target.checked)}
              className="h-3 w-3 text-cyan-600 bg-black border-slate-600 rounded focus:ring-cyan-500 focus:ring-offset-0"
            />
            <label htmlFor="aspect" className="ml-2 text-xs text-slate-400 font-code">{t.maintainAspect}</label>
          </div>
        </section>

        {/* Adjustments */}
        <section>
          <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.transform}</label>
          <div className="flex gap-2 mb-2">
             <button 
               onClick={() => updateOption('rotate', (options.rotate - 90) % 360)}
               className="flex-1 py-1.5 border border-slate-700 bg-black/20 text-[10px] font-code text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50 transition-colors"
             >
               ROT -90°
             </button>
             <button 
               onClick={() => updateOption('rotate', (options.rotate + 90) % 360)}
               className="flex-1 py-1.5 border border-slate-700 bg-black/20 text-[10px] font-code text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50 transition-colors"
             >
               ROT +90°
             </button>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => updateOption('flipX', !options.flipX)}
              className={`flex-1 py-1.5 border text-[10px] font-code transition-colors ${options.flipX ? 'bg-cyan-900/40 border-cyan-500 text-cyan-400' : 'border-slate-700 bg-black/20 text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50'}`}
            >
              FLIP H
            </button>
            <button 
              onClick={() => updateOption('flipY', !options.flipY)}
              className={`flex-1 py-1.5 border text-[10px] font-code transition-colors ${options.flipY ? 'bg-cyan-900/40 border-cyan-500 text-cyan-400' : 'border-slate-700 bg-black/20 text-slate-400 hover:text-cyan-300 hover:border-cyan-500/50'}`}
            >
              FLIP V
            </button>
          </div>
        </section>

        {/* Filters */}
        <section>
           <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.filters}</label>
           <div className="space-y-3">
             <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <span className="text-xs text-slate-400 font-code">{t.grayscale}</span>
                <input 
                  type="checkbox" 
                  checked={options.grayscale}
                  onChange={(e) => updateOption('grayscale', e.target.checked)}
                  className="h-3 w-3 text-cyan-600 bg-black border-slate-600 rounded focus:ring-cyan-500 focus:ring-offset-0"
                />
             </div>
             <div className="flex items-center justify-between border-b border-slate-800 pb-2">
                <span className="text-xs text-slate-400 font-code">{t.sharpen}</span>
                <input 
                  type="checkbox" 
                  checked={options.sharpen}
                  onChange={(e) => updateOption('sharpen', e.target.checked)}
                  className="h-3 w-3 text-cyan-600 bg-black border-slate-600 rounded focus:ring-cyan-500 focus:ring-offset-0"
                />
             </div>
             <div>
                <div className="flex justify-between mb-1">
                  <span className="text-xs text-slate-400 font-code">{t.blur}</span>
                  <span className="text-[10px] text-cyan-500 font-code">{options.blur}px</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="20"
                  step="0.5"
                  value={options.blur}
                  onChange={(e) => updateOption('blur', Number(e.target.value))}
                  className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                />
             </div>
           </div>
        </section>

        {/* Watermark */}
        <section>
           <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.watermark}</label>
           <textarea
             rows={4}
             placeholder={t.watermarkPlaceholder}
             value={options.watermarkText}
             onChange={(e) => updateOption('watermarkText', e.target.value)}
             className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code placeholder-slate-600 rounded-sm"
           />
        </section>
      </div>

      <div className="p-4 border-t border-cyan-900/30 bg-slate-900/50 relative">
        <button
          onClick={onProcess}
          disabled={isProcessing}
          className={`w-full py-3 px-4 font-tech font-bold uppercase tracking-widest text-sm clip-button transition-all relative overflow-hidden group
            ${isProcessing 
              ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
              : 'bg-cyan-600 hover:bg-cyan-500 text-white shadow-[0_0_20px_rgba(6,182,212,0.4)] hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]'
            }
          `}
        >
          <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          {isProcessing ? t.processing : t.processBtn}
        </button>
      </div>
    </div>
  );
};

export type Language = 'en' | 'zh';

export enum ImageFormat {
  ORIGINAL = 'original',
  JPEG = 'jpeg',
  PNG = 'png',
  WEBP = 'webp',
  AVIF = 'avif',
  BMP = 'bmp'
}

export type RawPixelFormat = 'uyvy' | 'nv21' | 'rgba' | 'bgra' | 'rgb' | 'bgr';

export type WatermarkPosition = 'top-left' | 'top-right' | 'center' | 'bottom-left' | 'bottom-right';

export interface ProcessOptions {
  format: ImageFormat;
  quality: number; // 1-100
  width: number | null;
  height: number | null;
  maintainAspectRatio: boolean;
  resizeMode: 'cover' | 'contain' | 'fill' | 'inside' | 'outside';
  rotate: number; // degrees
  flipX: boolean;
  flipY: boolean;
  grayscale: boolean;
  blur: number; // 0-100
  sharpen: boolean;
  watermarkText: string;
  watermarkPosition: WatermarkPosition;
  // New fields for RAW handling
  rawWidth?: number;
  rawHeight?: number;
  rawPixelFormat?: RawPixelFormat;
}

export interface UploadResponse {
  id: string;
  filename: string;
  url: string;
  originalName: string;
  size: number;
  width?: number;
  height?: number;
  depth?: string;
  format?: string;
}

export interface ProcessResponse {
  url: string;
  filename: string;
  size: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language, RawPixelFormat } from './types';

// --- Sub-component: Fake Terminal Logs ---
const TerminalLogs = ({ isProcessing, lang }: { isProcessing: boolean; lang: Language }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const logMessages = [
    "INITIALIZING_CORE...",
    "LOADING_BUFFER_MEMORY...",
    "ANALYZING_PIXEL_DENSITY...",
    "DETECTING_RAW_HEADERS...",
    "QUANTIZING_COLOR_SPACE...",
    "APPLYING_MATRIX_TRANSFORM...",
    "OPTIMIZING_COMPRESSION...",
    "WRITING_EXIF_DATA...",
    "FINALIZING_OUTPUT_STREAM...",
    "CLEANING_TEMP_REGISTERS..."
  ];

  useEffect(() => {
    if (isProcessing) {
      setLogs([]);
      let index = 0;
      const interval = setInterval(() => {
        if (index < logMessages.length) {
          const prefix = `[${new Date().toLocaleTimeString('en-GB', { hour12: false })}] `;
          setLogs(prev => [...prev, prefix + logMessages[index]]);
          index++;
          // Auto scroll
          if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
      }, 300 + Math.random() * 200);
      return () => clearInterval(interval);
    }
  }, [isProcessing]);

  if (!isProcessing && logs.length === 0) return null;

  return (
    <div className="absolute bottom-4 right-4 w-64 h-32 bg-black/80 border border-green-500/50 p-2 font-code text-[10px] text-green-400 overflow-y-auto pointer-events-none z-50 rounded backdrop-blur-md shadow-lg" ref={scrollRef}>
      {logs.map((log, i) => (
        <div key={i} className="whitespace-nowrap">&gt; {log}</div>
      ))}
      {isProcessing && <div className="animate-pulse">&gt; _</div>}
    </div>
  );
};

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: '',
  watermarkPosition: 'bottom-right',
  rawWidth: undefined,
  rawHeight: undefined,
  rawPixelFormat: 'uyvy' // default
};

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);

  const t = {
    en: {
      appTitle: "TUKUKU",
      sloganTitle: "IMAGE PROCESSOR",
      uploadFailed: "CRITICAL ERROR: UPLOAD FAILED",
      processFailed: "PROCESSING ERROR",
      processedSuccess: "COMPILATION COMPLETE",
      preview: "VISUAL_FEED",
      noPreview: "NO VISUAL FEED FOR RAW DATA",
      originalSize: "INPUT_SIZE",
      newSize: "OUTPUT_SIZE",
      savings: "EFFICIENCY",
      startOver: "RESET_SYSTEM",
      download: "EXTRACT_DATA",
      serverDesc: "SECURE SERVER CONNECTION :: ESTABLISHED"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "图像处理器",
      uploadFailed: "严重错误：上传失败",
      processFailed: "处理错误",
      processedSuccess: "编译完成",
      preview: "视觉反馈",
      noPreview: "RAW 数据无视觉反馈",
      originalSize: "输入体积",
      newSize: "输出体积",
      savings: "效率提升",
      startOver: "重置系统",
      download: "提取数据",
      serverDesc: "安全连接 :: 已建立"
    }
  }[lang];

  // Helper to guess pixel format from extension
  const getFormatFromExt = (filename: string): RawPixelFormat => {
      const lower = filename.toLowerCase();
      if (lower.endsWith('.uyvy')) return 'uyvy';
      if (lower.endsWith('.nv21')) return 'nv21';
      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; 
  };

  // Helper to check for raw formats that browser can't render
  const isRawFormat = (filename: string) => {
      const exts = ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'];
      return exts.some(ext => filename.toLowerCase().endsWith(ext));
  };

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      const suggestedFormat = getFormatFromExt(data.originalName);
      const isRaw = isRawFormat(data.originalName);

      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null,
        rawWidth: isRaw ? (data.width || 1920) : undefined,
        rawHeight: isRaw ? (data.height || 1080) : undefined,
        rawPixelFormat: suggestedFormat
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();
      setResult(data);
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    if (depth === 'uchar') return null; 
    if (depth === 'ushort' || depth === 'short') return '16-BIT';
    if (depth === 'float') return '32-BIT FLOAT';
    if (depth === 'uint' || depth === 'int') return '32-BIT INT';
    return depth.toUpperCase();
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  return (
    <div className="flex flex-col h-full bg-transparent text-slate-300 font-sans selection:bg-cyan-500/30 selection:text-cyan-100">

      {/* Header */}
      <header className="border-b border-cyan-900/50 bg-[#020617]/90 backdrop-blur-md py-4 px-6 shadow-[0_0_20px_rgba(6,182,212,0.1)] relative z-20">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={handleReset}>
            <div className="w-10 h-10 bg-cyan-900/30 border border-cyan-500 rounded-none flex items-center justify-center relative overflow-hidden group-hover:border-cyan-400 transition-colors">
               <div className="absolute inset-0 bg-cyan-400/10 animate-pulse"></div>
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-cyan-400 relative z-10">
                 <path strokeLinecap="square" strokeLinejoin="miter" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z" />
               </svg>
            </div>
            <div>
              <h1 className="text-2xl font-tech font-bold tracking-widest text-cyan-50 hover-glitch" data-text={t.appTitle}>{t.appTitle}</h1>
              <div className="h-0.5 w-full bg-gradient-to-r from-cyan-500 to-transparent"></div>
            </div>
          </div>
          <div className="flex items-center gap-6">
             <button 
               onClick={toggleLang}
               className="flex items-center justify-center px-4 py-1.5 text-xs font-code font-bold text-cyan-400 border border-cyan-800 hover:bg-cyan-900/30 hover:border-cyan-500 transition-all uppercase tracking-wider"
             >
                [{lang === 'en' ? 'CN' : 'EN'}]
             </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden relative z-10">
        <div className="absolute inset-0 overflow-y-auto custom-scrollbar">
          <div className="max-w-7xl mx-auto p-6 h-full min-h-[calc(100vh-80px)]">

            {!currentFile ? (
              <div className="h-full flex flex-col justify-center items-center max-w-3xl mx-auto mt-20 md:mt-0">
                <div className="w-full text-center mb-12 relative">
                   <h2 className="text-5xl md:text-6xl font-tech font-black text-transparent bg-clip-text bg-gradient-to-b from-white to-slate-500 mb-6 tracking-tighter drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">
                     {t.sloganTitle}
                   </h2>
                </div>
                <div className="w-full max-w-xl">
                    <Dropzone onFileSelect={handleFileUpload} isUploading={isUploading} lang={lang} />
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full pb-10">
                {/* Left: Controls */}
                <div className="lg:col-span-4 h-full max-h-[850px]">
                  <Controls 
                    options={options} 
                    setOptions={setOptions} 
                    onProcess={handleProcess}
                    isProcessing={isProcessing}
                    originalDimensions={{ width: currentFile.width || 0, height: currentFile.height || 0 }}
                    lang={lang}
                    inputFormat={currentFile.originalName} 
                  />
                </div>

                {/* Right: Preview & Result */}
                <div className="lg:col-span-8 flex flex-col gap-6">
                  {/* Preview Area Container */}
                  <div className="bg-slate-900/50 border border-slate-700 rounded-none flex-1 flex flex-col relative overflow-hidden group h-[500px] lg:h-auto">
                    {/* Tech Decor */}
                    <div className="absolute top-0 left-0 p-2 z-20 flex gap-1">
                        <div className="w-16 h-1 bg-cyan-600/50"></div>
                        <div className="w-4 h-1 bg-cyan-600/50"></div>
                    </div>
                    <div className="absolute bottom-0 right-0 p-2 z-20 text-[10px] font-code text-slate-500 uppercase">
                        COORD: {options.width || 'AUTO'} x {options.height || 'AUTO'}
                    </div>

                    {/* Image Viewport */}
                    <div className="relative z-10 w-full h-full flex items-center justify-center p-8 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
                      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-cyan-900/5 to-transparent pointer-events-none"></div>

                      {/* Holographic Scanner Effect (Overlay when processing) */}
                      {isProcessing && (
                         <div className="absolute inset-0 z-30 pointer-events-none">
                            <div className="scanner-overlay"></div>
                            <div className="scanner-line"></div>
                         </div>
                      )}

                      {/* Terminal Logs (Bottom Right Overlay) */}
                      <TerminalLogs isProcessing={isProcessing} lang={lang} />

                      {result ? (
                         <div className="flex flex-col items-center relative w-full h-full justify-center">
                            {/* Standard Result Display */}
                            <img 
                              src={result.url} 
                              alt="Processed" 
                              className="max-h-[500px] w-full object-contain shadow-[0_0_30px_rgba(6,182,212,0.15)] border border-slate-700" 
                            />

                            <div className="absolute top-4 left-4 mt-2 bg-green-900/30 text-green-400 px-4 py-1 border-l-2 border-green-500 flex items-center backdrop-blur-md z-40">
                               <svg className="w-4 h-4 mr-2 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                               <span className="font-code text-xs tracking-wider uppercase">{t.processedSuccess}</span>
                            </div>
                         </div>
                      ) : (
                        <div className="relative w-full h-full flex items-center justify-center">
                           {isRawFormat(currentFile.filename) ? (
                              <div className="flex flex-col items-center justify-center p-8 border border-slate-700 bg-slate-900/80 backdrop-blur-sm relative z-20">
                                 {/* Glitch Effect on Icon */}
                                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-16 h-16 text-yellow-600 mb-4 opacity-80">
                                    <path strokeLinecap="square" strokeLinejoin="miter" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                                 </svg>
                                 <span className="text-yellow-500 font-tech tracking-wider text-lg animate-pulse">{t.noPreview}</span>
                                 <span className="text-yellow-700 font-code text-xs mt-2 text-center max-w-xs uppercase border-t border-yellow-800/50 pt-2">
                                    {lang === 'en' ? 'Awaiting parameter configuration...' : '等待参数配置...'}
                                 </span>
                              </div>
                           ) : (
                             <>
                               <img 
                                 src={currentFile.url} 
                                 alt="Original" 
                                 decoding="async"
                                 className="max-h-[500px] object-contain shadow-2xl border border-slate-700 transition-all duration-300 z-20" 
                                 style={{
                                   transform: `rotate(${options.rotate}deg) scaleX(${options.flipX ? -1 : 1}) scaleY(${options.flipY ? -1 : 1})`,
                                   filter: `
                                     grayscale(${options.grayscale ? 1 : 0}) 
                                     blur(${options.blur}px)
                                     ${options.sharpen ? 'contrast(1.2) brightness(1.1)' : ''}
                                   `
                                 }} 
                               />
                               <div className="absolute top-4 right-4 bg-black/70 border border-cyan-500/30 text-cyan-400 text-[10px] font-code px-3 py-1 backdrop-blur-md uppercase tracking-widest z-20">
                                 ● {t.preview}
                               </div>
                             </>
                           )}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Data Readout / Actions */}
                  {result && (
                    <div className="bg-slate-900/80 border-t border-b border-cyan-900/50 p-4 flex items-center justify-between relative backdrop-blur-md">
                       <div className="absolute top-0 left-0 w-1 h-full bg-cyan-500"></div>

                       <div className="flex items-center gap-8">
                          <div className="text-xs font-code">
                             <p className="text-slate-500 uppercase tracking-wider mb-1">{t.originalSize}</p>
                             <p className="text-slate-200">
                               {formatSize(currentFile.size)} 
                               {getBitDepthLabel(currentFile.depth) && (
                                 <span className="text-slate-600 ml-2">[{getBitDepthLabel(currentFile.depth)}]</span>
                               )}
                             </p>
                          </div>

                          <div className="text-2xl text-slate-700 font-thin">/</div>

                          <div className="text-xs font-code">
                             <p className="text-slate-500 uppercase tracking-wider mb-1">{t.newSize}</p>
                             <p className="text-cyan-400 font-bold glow-text">{formatSize(result.size)}</p>
                          </div>

                          <div className="text-2xl text-slate-700 font-thin">/</div>

                          <div className="text-xs font-code">
                             <p className="text-slate-500 uppercase tracking-wider mb-1">{t.savings}</p>
                             <p className="text-green-400">
                               {currentFile.size > result.size 
                                 ? Math.round(((currentFile.size - result.size) / currentFile.size) * 100) + '%'
                                 : 'N/A'}
                             </p>
                          </div>
                       </div>

                       <div className="flex gap-4">
                         <button 
                           onClick={handleReset}
                           className="px-4 py-2 text-xs font-code font-bold text-slate-400 hover:text-white border border-transparent hover:border-slate-500 transition-all uppercase tracking-wider"
                         >
                           {t.startOver}
                         </button>
                         <a 
                           href={result.url} 
                           download={result.filename}
                           className="flex items-center gap-2 bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 font-tech font-bold uppercase tracking-widest text-xs clip-button shadow-[0_0_15px_rgba(6,182,212,0.4)] hover:shadow-[0_0_25px_rgba(6,182,212,0.6)] transition-all"
                         >
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="square" strokeLinejoin="miter" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                            {t.download}
                         </a>
                       </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;

import React from 'react';
import { ImageFormat, ProcessOptions, Language, RawPixelFormat, WatermarkPosition } from '../types';

interface ControlsProps {
  options: ProcessOptions;
  setOptions: React.Dispatch<React.SetStateAction<ProcessOptions>>;
  onProcess: () => void;
  isProcessing: boolean;
  originalDimensions?: { width: number; height: number };
  lang: Language;
  inputFormat?: string; // Passed from parent to detect if raw inputs are needed
}

export const Controls: React.FC<ControlsProps> = ({ 
  options, 
  setOptions, 
  onProcess, 
  isProcessing,
  originalDimensions,
  lang,
  inputFormat
}) => {

  const t = {
    en: {
      settings: "SYSTEM_CONFIG",
      sourceSettings: "RAW_DATA_INPUT",
      sourceDesc: "Required: Specify format & dimensions.",
      format: "OUTPUT_FORMAT",
      pixelFormat: "PIXEL_FORMAT",
      quality: "COMPRESSION",
      resize: "DIMENSIONS",
      maintainAspect: "LOCK_ASPECT",
      transform: "TRANSFORM",
      filters: "FILTERS",
      grayscale: "GRAYSCALE",
      sharpen: "SHARPEN",
      blur: "GAUSSIAN_BLUR",
      watermark: "WATERMARK",
      watermarkPos: "POSITION",
      posTL: "Top Left",
      posTR: "Top Right",
      posC: "Center",
      posBL: "Bottom Left",
      posBR: "Bottom Right",
      processBtn: "EXECUTE_PROCESS",
      processing: "PROCESSING..."
    },
    zh: {
      settings: "系统配置",
      sourceSettings: "RAW 数据源",
      sourceDesc: "必填：指定格式与尺寸",
      format: "输出格式",
      pixelFormat: "像素格式",
      quality: "压缩质量",
      resize: "尺寸调整",
      maintainAspect: "锁定比例",
      transform: "变换控制",
      filters: "图像滤镜",
      grayscale: "灰度模式",
      sharpen: "锐化增强",
      blur: "高斯模糊",
      watermark: "水印叠加",
      watermarkPos: "位置",
      posTL: "左上",
      posTR: "右上",
      posC: "居中",
      posBL: "左下",
      posBR: "右下",
      processBtn: "执行处理",
      processing: "处理中..."
    }
  }[lang];

  const updateOption = <K extends keyof ProcessOptions>(key: K, value: ProcessOptions[K]) => {
    setOptions(prev => ({ ...prev, [key]: value }));
  };

  // Helper to handle dimension changes with aspect ratio locking
  const handleDimensionChange = (dimension: 'width' | 'height', value: string) => {
    const numValue = value ? Number(value) : null;

    setOptions(prev => {
      const next = { ...prev, [dimension]: numValue };

      // Auto-calculate the other dimension if aspect ratio is locked and we have original dims
      // Note: originalDimensions.width > 0 check ensures we don't divide by zero or use invalid metadata
      if (
        prev.maintainAspectRatio && 
        originalDimensions && 
        originalDimensions.width > 0 && 
        originalDimensions.height > 0 && 
        numValue !== null
      ) {
        const ratio = originalDimensions.width / originalDimensions.height;

        if (dimension === 'width') {
          next.height = Math.round(numValue / ratio);
        } else {
          next.width = Math.round(numValue * ratio);
        }
      }
      return next;
    });
  };

  // Helper to handle toggling the checkbox
  const handleAspectToggle = (checked: boolean) => {
    setOptions(prev => {
      const next = { ...prev, maintainAspectRatio: checked };
      // If turning ON, and we have a width, sync the height immediately
      if (
        checked && 
        originalDimensions && 
        originalDimensions.width > 0 && 
        originalDimensions.height > 0 && 
        next.width
      ) {
         const ratio = originalDimensions.width / originalDimensions.height;
         next.height = Math.round(next.width / ratio);
      }
      return next;
    });
  };

  const isRaw = inputFormat && (
      ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'].some(ext => inputFormat.toLowerCase().endsWith(ext))
  );

  return (
    <div className="bg-slate-900/80 backdrop-blur-md rounded-none border border-cyan-900/50 flex flex-col h-full overflow-hidden relative">
      {/* Header Accent */}
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-600 to-transparent"></div>

