      posTL: "Top Left",
      posTR: "Top Right",
      posC: "Center",
      posBL: "Bottom Left",
      posBR: "Bottom Right",
      processBtn: "EXECUTE_PROCESS",
      processing: "PROCESSING...",
      rotBtn: "ROT +90°",
      flipH: "FLIP H",
