                />
             </div>
           </div>
        </section>

        {/* Watermark */}
        <section>
           <label className="block text-xs font-bold text-cyan-500 mb-3 font-tech tracking-wider uppercase">{t.watermark}</label>
           <div className="mb-2">
             <label className="block text-[10px] text-slate-500 mb-1 font-code">{t.watermarkPos}</label>
             <select 
               value={options.watermarkPosition || 'bottom-right'}
               onChange={(e) => updateOption('watermarkPosition', e.target.value as WatermarkPosition)}
               className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code uppercase"
             >
               <option value="top-left">{t.posTL}</option>
               <option value="top-right">{t.posTR}</option>
               <option value="center">{t.posC}</option>
               <option value="bottom-left">{t.posBL}</option>
               <option value="bottom-right">{t.posBR}</option>
             </select>
           </div>
           <textarea
             rows={2}
             placeholder=""
             value={options.watermarkText}
             onChange={(e) => updateOption('watermarkText', e.target.value)}
             className="w-full bg-black/40 border border-slate-700 text-cyan-100 text-xs py-2 px-3 focus:outline-none focus:border-cyan-500 font-code rounded-sm"
           />
        </section>
      </div>

      <div className="p-4 border-t border-cyan-900/30 bg-slate-900/50 relative">
        <button
          onClick={onProcess}
          disabled={isProcessing}
          className={`w-full py-3 px-4 font-tech font-bold uppercase tracking-widest text-sm clip-button transition-all relative overflow-hidden group
            ${isProcessing 
              ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
              : 'bg-cyan-600 hover:bg-cyan-500 text-white shadow-[0_0_20px_rgba(6,182,212,0.4)] hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]'
            }
          `}
        >
          <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          {isProcessing ? t.processing : t.processBtn}
        </button>
      </div>
    </div>
  );
};

import express from 'express';
import multer from 'multer';
import sharp from 'sharp';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import bmp from 'bmp-js'; 
import { v4 as uuidv4 } from 'uuid';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = 3000;

// Middleware
app.use(cors());
app.use(express.json());

// Directories
const UPLOAD_DIR = path.join(__dirname, 'uploads');
const PROCESSED_DIR = path.join(__dirname, 'processed');

if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR);
if (!fs.existsSync(PROCESSED_DIR)) fs.mkdirSync(PROCESSED_DIR);

// Storage config
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, UPLOAD_DIR);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = uuidv4();
    cb(null, uniqueSuffix + path.extname(file.originalname));
  }
});

const upload = multer({ 
  storage: storage,
  limits: { fileSize: 20 * 1024 * 1024 } // 20MB
});

// Helper: Delete old files
const CLEANUP_INTERVAL = 30 * 60 * 1000; // 30 mins
setInterval(() => {
  const now = Date.now();
  [UPLOAD_DIR, PROCESSED_DIR].forEach(dir => {
    fs.readdir(dir, (err, files) => {
      if (err) return;
      files.forEach(file => {
        const filePath = path.join(dir, file);
        fs.stat(filePath, (err, stats) => {
          if (err) return;
          if (now - stats.mtimeMs > CLEANUP_INTERVAL) {
            fs.unlink(filePath, () => {});
          }
        });
      });
    });
  });
}, CLEANUP_INTERVAL);

// Serve static files
app.use('/api/uploads', express.static(UPLOAD_DIR));
app.use('/api/processed', express.static(PROCESSED_DIR));

// --- PIXEL CONVERSION HELPERS ---

function convertYuvPixelToRgb(y, u, v, outBuffer, offset) {
  // Standard BT.601 conversion
  const c = y - 16;
  const d = u - 128;
  const e = v - 128;

  const r = (298 * c + 409 * e + 128) >> 8;
  const g = (298 * c - 100 * d - 208 * e + 128) >> 8;
  const b = (298 * c + 516 * d + 128) >> 8;

  outBuffer[offset] = Math.max(0, Math.min(255, r));     // R
  outBuffer[offset + 1] = Math.max(0, Math.min(255, g)); // G
  outBuffer[offset + 2] = Math.max(0, Math.min(255, b)); // B
  outBuffer[offset + 3] = 255; // Alpha
}

/**
 * UYVY to RGBA (YUV 4:2:2 Packed)
 */
function uyvyToRgba(buffer, width, height) {
  const numPixels = width * height;
  const rgba = Buffer.alloc(numPixels * 4);
  let ptr = 0;
  let outPtr = 0;

  for (let i = 0; i < numPixels / 2; i++) {
    if (ptr + 3 >= buffer.length) break;
    const u = buffer[ptr];
    const y0 = buffer[ptr + 1];
    const v = buffer[ptr + 2];
    const y1 = buffer[ptr + 3];
    ptr += 4;
    convertYuvPixelToRgb(y0, u, v, rgba, outPtr);
    outPtr += 4;
    convertYuvPixelToRgb(y1, u, v, rgba, outPtr);
    outPtr += 4;
  }
  return rgba;
}

/**
 * YUY2 to RGBA (YUV 4:2:2 Packed)
 */
function yuy2ToRgba(buffer, width, height) {
  const numPixels = width * height;
  const rgba = Buffer.alloc(numPixels * 4);
  let ptr = 0;
  let outPtr = 0;

  for (let i = 0; i < numPixels / 2; i++) {
    if (ptr + 3 >= buffer.length) break;
    const y0 = buffer[ptr];
    const u = buffer[ptr + 1];
    const y1 = buffer[ptr + 2];
    const v = buffer[ptr + 3];
    ptr += 4;
    convertYuvPixelToRgb(y0, u, v, rgba, outPtr);
    outPtr += 4;
    convertYuvPixelToRgb(y1, u, v, rgba, outPtr);
    outPtr += 4;
  }
  return rgba;
}

/**
 * NV21 to RGBA (YUV 4:2:0 Semi-Planar)
 */
function nv21ToRgba(buffer, width, height) {
  const numPixels = width * height;
  const rgba = Buffer.alloc(numPixels * 4);

  const ySize = width * height;
  const uvOffset = ySize;

  if (buffer.length < width * height * 1.5) {
      console.warn("Buffer too small for NV21 at " + width + "x" + height);
  }

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
       const yIndex = y * width + x;
       const yVal = buffer[yIndex];

       const uvIndex = uvOffset + Math.floor(y/2) * width + Math.floor(x/2) * 2;

       let vVal = 128, uVal = 128;
       if (uvIndex + 1 < buffer.length) {
         vVal = buffer[uvIndex];
         uVal = buffer[uvIndex + 1];
       }

       const outPtr = yIndex * 4;
       convertYuvPixelToRgb(yVal, uVal, vVal, rgba, outPtr);
    }
  }
  return rgba;
}

/**
 * Robust Image Loader Helper
 */
async function getSharpInstance(filePath, rawOptions = {}) {
  const ext = path.extname(filePath).toLowerCase();

  // FIX: Explicitly exclude standard formats from RAW processing
  // This prevents standard JPGs from being read as raw bytes if options are accidentally passed
  const STANDARD_FORMATS = ['.jpg', '.jpeg', '.png', '.webp', '.gif', '.avif', '.tiff', '.tif', '.svg'];
  const isStandard = STANDARD_FORMATS.includes(ext);

  // Detect if we need to perform RAW processing
  const explicitRaw = !isStandard && !!(rawOptions.width && rawOptions.height && rawOptions.pixelFormat);
  const implicitRaw = ['.uyvy', '.yuv', '.nv21', '.rgb', '.rgba', '.bgra', '.bgr', '.bin', '.raw'].includes(ext);

  if (!isStandard && (explicitRaw || implicitRaw)) {
    const stats = fs.statSync(filePath);
    const size = stats.size;
    let width, height;

    // Default format if implicit
    let pixelFormat = rawOptions.pixelFormat || 'uyvy'; 

    if (rawOptions.width && rawOptions.height) {
        width = rawOptions.width;
        height = rawOptions.height;
        console.log(`Using manual raw config: ${width}x${height} ${pixelFormat}`);
    } else {
        const KNOWN_RESOLUTIONS = {
            5898240: [1920, 1536], 
            4147200: [1920, 1080], 
            1843200: [1280, 720], 
            614400:  [640, 480],   
        };
        const dims = KNOWN_RESOLUTIONS[size];
        if (dims) {
            [width, height] = dims;
            console.log(`Guessed resolution from size ${size}: ${width}x${height}`);
        }
    }

    if (width && height) {
      const buffer = fs.readFileSync(filePath);
      let rgbaBuffer;

      switch (pixelFormat.toLowerCase()) {
          case 'uyvy':
              rgbaBuffer = uyvyToRgba(buffer, width, height);
              break;
          case 'yuy2':
              rgbaBuffer = yuy2ToRgba(buffer, width, height);
              break;
          case 'nv21':
              rgbaBuffer = nv21ToRgba(buffer, width, height);
              break;
          case 'rgba':
              // Sharp can handle raw RGBA (4 channels)
              return sharp(buffer, {
                  raw: { width, height, channels: 4 }
              }).toColorspace('srgb');
          case 'bgra':
              // Swap B and R channels for 4-channel BGRA -> RGBA
              rgbaBuffer = Buffer.from(buffer);
              for (let i = 0; i < rgbaBuffer.length; i += 4) {
                  const b = rgbaBuffer[i];
                  const r = rgbaBuffer[i + 2];
                  rgbaBuffer[i] = r;
                  rgbaBuffer[i + 2] = b;
              }
              break;
          case 'rgb':
              // Sharp handles 3 channel raw
              return sharp(buffer, {
                  raw: { width, height, channels: 3 }
              }).toColorspace('srgb');
          case 'bgr':
              // Swap B and R in 3-channel buffer
              const bgrBuf = Buffer.from(buffer);
              for (let i = 0; i < bgrBuf.length; i += 3) {
                  const b = bgrBuf[i];
                  const r = bgrBuf[i + 2];
                  bgrBuf[i] = r;
                  bgrBuf[i + 2] = b;
              }
              return sharp(bgrBuf, {
                  raw: { width, height, channels: 3 }
              }).toColorspace('srgb');
          default:
              console.warn(`Unknown pixel format ${pixelFormat}, defaulting to UYVY`);
              rgbaBuffer = uyvyToRgba(buffer, width, height);
              break;
      }

      // For cases where we manually created an RGBA buffer (UYVY, NV21, BGRA)
      return sharp(rgbaBuffer, {
        raw: {
          width: width,
          height: height,
          channels: 4
        }
      }).toColorspace('srgb');
    }
  }

  // --- BMP HANDLING (24-bit & 32-bit Robust Fix) ---
  if (ext === '.bmp') {
    try {
      console.log("Using Robust bmp-js decode for: " + filePath);
      const buffer = fs.readFileSync(filePath);
      const bitmap = bmp.decode(buffer);
      const rawData = bitmap.data; 

      const len = rawData.length;
      const width = bitmap.width;
      const height = bitmap.height;
      const rgba = Buffer.alloc(len);

      // Detect if image is effectively opaque (24-bit or 32-bit without transparency)
      let maxAlpha = 0;
      for (let i = 0; i < len; i += 4) {
           if (rawData[i] > maxAlpha) {
               maxAlpha = rawData[i];
           }
      }
      const forceOpaque = (maxAlpha === 0);

      // Map ABGR -> RGBA
      for (let i = 0; i < len; i += 4) {
        const a = rawData[i];
        const b = rawData[i + 1];
        const g = rawData[i + 2];
        const r = rawData[i + 3];

        rgba[i]     = r;                // R
        rgba[i + 1] = g;                // G
        rgba[i + 2] = b;                // B
        rgba[i + 3] = forceOpaque ? 255 : a; // A
      }

      return sharp(rgba, { 
        raw: { width, height, channels: 4 } 
      }).toColorspace('srgb');

    } catch (bmpError) { 
      console.error("BMP Manual Decode Error:", bmpError);
    }
  }

  // --- Standard Formats ---
  return sharp(filePath, { failOnError: false, limitInputPixels: false }).rotate().toColorspace('srgb');
}

// Routes
app.post('/api/upload', upload.single('image'), async (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  console.log(`Processing upload: ${req.file.originalname} (${req.file.size} bytes)`);

  try {
    const imagePipeline = await getSharpInstance(req.file.path);
    const metadata = await imagePipeline.metadata();

    res.json({
      id: path.parse(req.file.filename).name,
      filename: req.file.filename,
      url: `/api/uploads/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: metadata.width,
      height: metadata.height,
      format: metadata.format,
      depth: metadata.depth
    });
  } catch (error) {
    console.error('Metadata extraction failed:', error.message);
    res.json({
      id: path.parse(req.file.filename).name,
      filename: req.file.filename,
      url: `/api/uploads/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: 0, 
      height: 0
    });
  }
});

app.post('/api/process', async (req, res) => {
  const { id, options } = req.body;

  if (!id || !options) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const files = fs.readdirSync(UPLOAD_DIR);
  const originalFile = files.find(f => f.startsWith(id));

  if (!originalFile) {
    return res.status(404).json({ error: 'File not found or expired' });
  }

  const inputPath = path.join(UPLOAD_DIR, originalFile);

  let format = options.format;
  if (format === 'original') {
    format = path.extname(originalFile).slice(1).toLowerCase();
    // Map raw extensions to default png output
    if (['uyvy', 'yuv', 'nv21', 'rgb', 'raw', 'bin', 'bgra', 'rgba'].includes(format)) format = 'png';
  }
  if (format === 'jpg') format = 'jpeg';
  if (['uyvy', 'yuv', 'nv21', 'rgb', 'raw', 'bin', 'bgra', 'rgba'].includes(format)) format = 'png';

  const outputFilename = `tuku_${id}_${Date.now()}.${format}`;
  const outputPath = path.join(PROCESSED_DIR, outputFilename);

  console.log(`Processing image ${id} -> ${format}`);

  try {
    const rawOptions = {
        width: options.rawWidth,
        height: options.rawHeight,
        pixelFormat: options.rawPixelFormat
    };

    const instance = await getSharpInstance(inputPath, rawOptions);
    const metadata = await instance.metadata();

    let pipeline = instance.clone();
    pipeline = pipeline.ensureAlpha(); 

    let currentWidth = metadata.width;
    let currentHeight = metadata.height;

    // 1. Resize
    if ((options.width && options.width > 0) || (options.height && options.height > 0)) {
      if (options.width && options.height) {
         currentWidth = options.width;
         currentHeight = options.height;
      } else if (options.width) {
         currentWidth = options.width;
         if (options.maintainAspectRatio) {
            currentHeight = Math.round(metadata.height * (options.width / metadata.width));
         }
      } else if (options.height) {
         currentHeight = options.height;
         if (options.maintainAspectRatio) {
             currentWidth = Math.round(metadata.width * (options.height / metadata.height));
         }
      }

      pipeline = pipeline.resize({
        width: options.width || null,
        height: options.height || null,
        fit: options.maintainAspectRatio ? (options.resizeMode || 'cover') : 'fill'
      });
    }

    // 2. Rotate & Flip
    if (options.rotate) {
        pipeline = pipeline.rotate(options.rotate);
        // Note: we don't strictly need to swap currentWidth/Height here anymore because
        // we re-read dimensions before watermark, but let's keep logic cleaner.
    }
    if (options.flipX) pipeline = pipeline.flop();
    if (options.flipY) pipeline = pipeline.flip();

    // 3. Filters
    if (options.grayscale) pipeline = pipeline.grayscale();
    if (options.blur > 0) pipeline = pipeline.blur(0.3 + options.blur);
    if (options.sharpen) pipeline = pipeline.sharpen();

    // 4. Watermark
    if (options.watermarkText) {
       // CRITICAL: Force render to buffer to ensure we have exact dimensions after resize/rotate
       // This prevents "Image to composite must have same dimensions or smaller" errors
       // caused by slight mismatches between manual calc and Sharp's internal state.
       const intermediateBuffer = await pipeline.png().toBuffer();
       pipeline = sharp(intermediateBuffer);

       const tempMeta = await pipeline.metadata();
       const svgWidth = tempMeta.width;
       const svgHeight = tempMeta.height;

       const fontSize = Math.max(Math.floor(svgWidth * 0.03), 20); // Scale with image, min 20px
       const lineHeight = fontSize * 1.2;
       const padding = fontSize; 

       const escapeXml = (unsafe) => {
          return unsafe.replace(/[<>&'"]/g, (c) => {
            switch (c) {
              case '<': return '&lt;';
              case '>': return '&gt;';
              case '&': return '&amp;';
              case '\'': return '&apos;';
              case '"': return '&quot;';
            }
          });
       };

       const lines = options.watermarkText.split(/\r?\n/);
       const pos = options.watermarkPosition || 'bottom-right';

       let startX, startY, textAnchor;
       const totalTextHeight = (lines.length - 1) * lineHeight;

       switch (pos) {
         case 'top-left':
           textAnchor = 'start';
           startX = padding;
           startY = padding + fontSize; // Approx baseline of first line
           break;
         case 'top-right':
           textAnchor = 'end';
           startX = svgWidth - padding;
           startY = padding + fontSize;
           break;
         case 'center':
           textAnchor = 'middle';
           startX = svgWidth / 2;
           // Vertically center the block of text
           startY = (svgHeight / 2) - ((lines.length * lineHeight) / 2) + fontSize;
           break;
         case 'bottom-left':
           textAnchor = 'start';
           startX = padding;
           startY = svgHeight - padding - totalTextHeight;
           break;
         case 'bottom-right':
         default:
           textAnchor = 'end';
           startX = svgWidth - padding;
           startY = svgHeight - padding - totalTextHeight;
           break;
       }

       const tspans = lines.map((line, i) => {
          const safeLine = escapeXml(line);
          const dy = i === 0 ? 0 : lineHeight;
          return `<tspan x="${startX}" dy="${dy}">${safeLine}</tspan>`;
       }).join('');

       const svgText = `
        <svg width="${svgWidth}" height="${svgHeight}">
          <style>
            .watermark { 
              fill: rgba(255, 255, 255, 0.85); 
              font-size: ${fontSize}px; 
              font-weight: bold; 
              font-family: 'Noto Sans CJK SC', 'Microsoft YaHei', sans-serif; 
              text-anchor: ${textAnchor};
              text-shadow: 2px 2px 4px rgba(0,0,0,0.8); 
            }
          </style>
          <text x="${startX}" y="${startY}" class="watermark">${tspans}</text>
        </svg>`;

       pipeline = pipeline.composite([{
          input: Buffer.from(svgText),
          gravity: 'center' 
       }]);
    }

    // 5. Output Generation
    if (format === 'bmp') {
        const { data: buffer, info } = await pipeline
          .toColorspace('srgb')
          .raw()
          .toBuffer({ resolveWithObject: true });

        // Convert RGBA -> ABGR for bmp-js
        const abgrBuffer = Buffer.alloc(buffer.length);
        for (let i = 0; i < buffer.length; i += 4) {
          const r = buffer[i];
          const g = buffer[i + 1];
          const b = buffer[i + 2];
          const a = buffer[i + 3];

          abgrBuffer[i]     = a; 
          abgrBuffer[i + 1] = b; 
          abgrBuffer[i + 2] = g; 
          abgrBuffer[i + 3] = r; 
        }

        const rawData = {
          data: abgrBuffer,
          width: info.width,
          height: info.height
        };
        const bmpData = bmp.encode(rawData);
        fs.writeFileSync(outputPath, bmpData.data);

    } else {
        if (['jpeg', 'jpg'].includes(format)) {
             pipeline = pipeline.flatten({ background: '#ffffff' });
             pipeline = pipeline.jpeg({ quality: options.quality });
        } else if (format === 'png') {
            pipeline = pipeline.png();
        } else if (format === 'webp') {
            pipeline = pipeline.webp({ quality: options.quality });
        } else if (format === 'avif') {
            pipeline = pipeline.avif({ quality: options.quality });
        } else {
            pipeline = pipeline.toFormat(format);
        }

        await pipeline.toFile(outputPath);
    }

    const stats = fs.statSync(outputPath);
    console.log(`Processing complete: ${outputFilename}`);

    res.json({
      url: `/api/processed/${outputFilename}`,
      filename: outputFilename,
      size: stats.size
    });

  } catch (error) {
    console.error('Processing error details:', error);
    const msg = error.message.includes('unsupported image format') 
      ? 'Input format corrupted or unsupported.' 
      : error.message;

    res.status(500).json({ error: `Processing failed: ${msg}` });
  }
});

