import React, { useRef, useState } from 'react';
import { Language } from '../types';

interface DropzoneProps {
  onFileSelect: (file: File) => void;
  isUploading: boolean;
  lang: Language;
  processedCount: number;
}

export const Dropzone: React.FC<DropzoneProps> = ({ onFileSelect, isUploading, lang, processedCount }) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = {
    en: {
      uploading: "UPLOADING DATA STREAM...",
      mainText: "UPLOAD",
      formats: "JPG, PNG, WEBP, BMP, RAW (UYVY, NV21, RGBA...)",
      limit: "MAX 20MB",
      formatError: "ERROR: INVALID FILE FORMAT",
      sizeError: "ERROR: FILE SIZE EXCEEDS 20MB LIMIT",
      processedCount: "PROCESSED IMAGES"
    },
    zh: {
      uploading: "数据流上传中...",
      mainText: "上传",
      formats: "支持 JPG, PNG, BMP, RAW (UYVY, NV21, RGBA...)",
      limit: "最大 20MB",
      formatError: "错误：不支持的文件格式",
      sizeError: "错误：文件大小超过 20MB 限制",
      processedCount: "已成功处理图片数"
    }
  }[lang];

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      validateAndUpload(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      validateAndUpload(e.target.files[0]);
    }
  };

  const validateAndUpload = (file: File) => {
    const validExtensions = [
      '.jpg', '.jpeg', '.png', '.webp', '.bmp', '.gif', '.heic', 
      '.uyvy', '.yuv', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.nv21', '.bin'
    ];

    const fileExt = '.' + file.name.split('.').pop()?.toLowerCase();
    const isValidExt = validExtensions.includes(fileExt);
    const isImageMime = file.type.startsWith('image/');

    if (!isValidExt && !isImageMime) {
      alert(t.formatError);
      return;
    }
    if (file.size > 20 * 1024 * 1024) {
      alert(t.sizeError);
      return;
    }
    onFileSelect(file);
  };

  return (
    <div
      onClick={() => !isUploading && fileInputRef.current?.click()}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`
        relative w-full h-80 rounded-none flex flex-col items-center justify-center cursor-pointer transition-all duration-300 group overflow-hidden
        ${isDragOver 
          ? 'bg-cyan-900/20' 
          : 'bg-slate-900/40 hover:bg-slate-800/60'}
        ${isUploading ? 'pointer-events-none' : ''}
        backdrop-blur-sm
      `}
    >
      {/* Animated Rotating Border Effect */}
      <div className={`absolute inset-0 pointer-events-none opacity-50 ${isDragOver || isUploading ? 'opacity-100' : 'group-hover:opacity-100'}`}>
          <svg className="absolute inset-0 w-full h-full" xmlns="http://www.w3.org/2000/svg">
              <defs>
                  <linearGradient id="grad1" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" style={{stopColor:'#06b6d4', stopOpacity:0}} />
                      <stop offset="50%" style={{stopColor:'#06b6d4', stopOpacity:1}} />
                      <stop offset="100%" style={{stopColor:'#06b6d4', stopOpacity:0}} />
                  </linearGradient>
              </defs>
              <rect x="2" y="2" width="99%" height="99%" fill="none" stroke="url(#grad1)" strokeWidth="2" strokeDasharray="200, 200" strokeDashoffset="0">
                  <animate attributeName="stroke-dashoffset" from="400" to="0" dur="4s" repeatCount="indefinite" />
              </rect>
          </svg>
      </div>

      {/* Decorative Corners */}
      <div className="absolute top-0 left-0 w-3 h-3 border-t-2 border-l-2 border-cyan-500"></div>
      <div className="absolute top-0 right-0 w-3 h-3 border-t-2 border-r-2 border-cyan-500"></div>
      <div className="absolute bottom-0 left-0 w-3 h-3 border-b-2 border-l-2 border-cyan-500"></div>
      <div className="absolute bottom-0 right-0 w-3 h-3 border-b-2 border-r-2 border-cyan-500"></div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleChange} 
        className="hidden" 
        accept="image/*,.uyvy,.yuv,.raw,.rgb,.bgr,.bin,.nv21,.rgba,.bgra"
      />

      {isUploading ? (
        <div className="flex flex-col items-center z-10">
           <div className="relative w-16 h-16 mb-6">
              <div className="absolute inset-0 border-4 border-slate-700 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-cyan-500 rounded-full border-t-transparent animate-spin"></div>
              {/* Core Pulse */}
              <div className="absolute inset-4 bg-cyan-500/20 rounded-full animate-pulse"></div>
           </div>
           <p className="text-lg font-tech tracking-widest text-cyan-400 animate-pulse">{t.uploading}</p>
        </div>
      ) : (
        <div className="flex flex-col items-center z-10 group-hover:scale-105 transition-transform duration-300">
          <div className="bg-slate-800/50 p-6 rounded-full mb-6 border border-cyan-500/30 group-hover:border-cyan-400/80 group-hover:shadow-[0_0_25px_rgba(6,182,212,0.3)] transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-12 h-12 text-cyan-400">
              <path strokeLinecap="square" strokeLinejoin="miter" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5m-13.5-9L12 3m0 0l4.5 4.5M12 3v13.5" />
            </svg>
          </div>
          <p className="text-3xl font-bold text-white mb-3 font-tech tracking-[0.2em]">{t.mainText}</p>

          <div className="flex flex-col items-center gap-1">
            <p className="text-xs text-slate-400 max-w-sm text-center font-code uppercase tracking-wider">
              {t.formats}
            </p>
            <p className="text-[10px] text-cyan-600 font-code font-bold border border-cyan-900/50 px-2 py-0.5 rounded bg-cyan-900/10">
              {t.limit}
            </p>
            <p className="text-[10px] text-slate-500 font-code mt-1 opacity-70 group-hover:opacity-100 transition-opacity">
              {t.processedCount}: <span className="text-cyan-400 font-bold">{processedCount}</span>
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language, RawPixelFormat } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: '',
  watermarkPosition: 'bottom-right',
  rawWidth: undefined,
  rawHeight: undefined,
  rawPixelFormat: 'uyvy' // default
};

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);
  const [totalProcessed, setTotalProcessed] = useState(0);

  const t = {
    en: {
      appTitle: "TUKUKU",
      sloganTitle: "IMAGE PROCESSOR",
      uploadFailed: "CRITICAL ERROR: UPLOAD FAILED",
      processFailed: "PROCESSING ERROR",
      processedSuccess: "RENDER_COMPLETE",
      preview: "VISUAL_FEED",
      noPreview: "NO VISUAL FEED FOR RAW DATA",
      originalSize: "INPUT_SIZE",
      newSize: "OUTPUT_SIZE",
      savings: "EFFICIENCY",
      startOver: "RESET_SYSTEM",
      download: "EXTRACT_DATA",
      serverDesc: "SECURE SERVER CONNECTION :: ESTABLISHED",
      status: "STATUS",
      coord: "COORD",
      auto: "AUTO"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "图像处理器",
      uploadFailed: "严重错误：上传失败",
      processFailed: "处理错误",
      processedSuccess: "渲染完毕",
      preview: "视觉反馈",
      noPreview: "RAW 数据无视觉反馈",
      originalSize: "输入体积",
      newSize: "输出体积",
      savings: "效率提升",
      startOver: "重置系统",
      download: "提取数据",
      serverDesc: "安全连接 :: 已建立",
      status: "状态",
      coord: "尺寸",
      auto: "自动"
    }
  }[lang];

  // Fetch stats on load
  useEffect(() => {
    fetch('/api/stats')
      .then(res => res.json())
      .then(data => {
        if (data.processedCount) setTotalProcessed(data.processedCount);
      })
      .catch(err => console.error("Failed to load stats", err));
  }, []);

  // Helper to guess pixel format from extension
  const getFormatFromExt = (filename: string): RawPixelFormat => {
      const lower = filename.toLowerCase();
      if (lower.endsWith('.uyvy')) return 'uyvy';
      if (lower.endsWith('.nv21')) return 'nv21';
      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; 
  };

  // Helper to check for raw formats that browser can't render
  const isRawFormat = (filename: string) => {
      const exts = ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'];
      return exts.some(ext => filename.toLowerCase().endsWith(ext));
  };

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      const suggestedFormat = getFormatFromExt(data.originalName);
      const isRaw = isRawFormat(data.originalName);

      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null,
        rawWidth: isRaw ? (data.width || 1920) : undefined,
        rawHeight: isRaw ? (data.height || 1080) : undefined,
        rawPixelFormat: suggestedFormat
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();

      // Fix for flashing: Preload the image before showing it
      await new Promise((resolve) => {
        const img = new Image();
        img.src = data.url;
        img.onload = resolve;
        img.onerror = resolve; // Resolve even on error to allow UI to show (maybe error placeholder)
      });

      setResult(data);
      // Increment local counter immediately to reflect success
      setTotalProcessed(prev => prev + 1);

    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    if (depth === 'uchar') return null; 
    if (depth === 'ushort' || depth === 'short') return '16-BIT';
    if (depth === 'float') return '32-BIT FLOAT';
    if (depth === 'uint' || depth === 'int') return '32-BIT INT';
    return depth.toUpperCase();
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  return (
    <div className="flex flex-col h-full bg-transparent text-slate-300 font-sans selection:bg-cyan-500/30 selection:text-cyan-100">

      {/* Header */}
      <header className="border-b border-cyan-900/50 bg-[#020617]/90 backdrop-blur-md py-4 px-6 shadow-[0_0_20px_rgba(6,182,212,0.1)] relative z-20">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
