app.post('/api/process', async (req, res) => {
  const { id, options } = req.body;

  if (!id || !options) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const files = fs.readdirSync(UPLOAD_DIR);
  const originalFile = files.find(f => f.startsWith(id));

  if (!originalFile) {
    return res.status(404).json({ error: 'File not found or expired' });
  }

  const inputPath = path.join(UPLOAD_DIR, originalFile);

  let format = options.format;
  if (format === 'original') {
    format = path.extname(originalFile).slice(1).toLowerCase();
    if (['uyvy', 'yuv', 'nv21', 'rgb', 'raw', 'bin', 'bgra', 'rgba'].includes(format)) format = 'png';
  }
  if (format === 'jpg') format = 'jpeg';
  if (['uyvy', 'yuv', 'nv21', 'rgb', 'raw', 'bin', 'bgra', 'rgba'].includes(format)) format = 'png';

  const outputFilename = `tuku_${id}_${Date.now()}.${format}`;
  const outputPath = path.join(PROCESSED_DIR, outputFilename);

  console.log(`Processing image ${id} -> ${format}`);

  try {
    const rawOptions = {
        width: options.rawWidth,
        height: options.rawHeight,
        pixelFormat: options.rawPixelFormat
    };

    const instance = await getSharpInstance(inputPath, rawOptions);
    const metadata = await instance.metadata();
    let pipeline = instance.clone();
    pipeline = pipeline.ensureAlpha(); 

    if ((options.width && options.width > 0) || (options.height && options.height > 0)) {
      pipeline = pipeline.resize({
        width: options.width || null,
        height: options.height || null,
        fit: options.maintainAspectRatio ? (options.resizeMode || 'cover') : 'fill'
      });
    }

    if (options.rotate && options.rotate !== 0) {
        const intermediate = await pipeline.png().toBuffer();
        pipeline = sharp(intermediate); 
        pipeline = pipeline.rotate(options.rotate); 
    }

    if (options.flipX) pipeline = pipeline.flop();
    if (options.flipY) pipeline = pipeline.flip();

    if (options.grayscale) pipeline = pipeline.grayscale();
    if (options.blur > 0) pipeline = pipeline.blur(0.3 + options.blur);
    if (options.sharpen) pipeline = pipeline.sharpen();

    if (options.watermarkText) {
       const intermediateBuffer = await pipeline.png().toBuffer();
       pipeline = sharp(intermediateBuffer);

       const tempMeta = await pipeline.metadata();
       const svgWidth = tempMeta.width;
       const svgHeight = tempMeta.height;

       const fontSize = Math.max(Math.floor(svgWidth * 0.03), 20); 
       const lineHeight = fontSize * 1.2;
       const padding = fontSize; 

       const escapeXml = (unsafe) => {
          return unsafe.replace(/[<>&'"]/g, (c) => {
            switch (c) {
              case '<': return '&lt;';
              case '>': return '&gt;';
              case '&': return '&amp;';
              case '\'': return '&apos;';
              case '"': return '&quot;';
            }
          });
       };

       const lines = options.watermarkText.split(/\r?\n/);
       const pos = options.watermarkPosition || 'bottom-right';

       let startX, startY, textAnchor;
       const totalTextHeight = (lines.length - 1) * lineHeight;

       switch (pos) {
         case 'top-left': textAnchor = 'start'; startX = padding; startY = padding + fontSize; break;
         case 'top-right': textAnchor = 'end'; startX = svgWidth - padding; startY = padding + fontSize; break;
         case 'center': textAnchor = 'middle'; startX = svgWidth / 2; startY = (svgHeight / 2) - ((lines.length * lineHeight) / 2) + fontSize; break;
         case 'bottom-left': textAnchor = 'start'; startX = padding; startY = svgHeight - padding - totalTextHeight; break;
         case 'bottom-right': default: textAnchor = 'end'; startX = svgWidth - padding; startY = svgHeight - padding - totalTextHeight; break;
       }

       const tspans = lines.map((line, i) => {
          const safeLine = escapeXml(line);
          const dy = i === 0 ? 0 : lineHeight;
          return `<tspan x="${startX}" dy="${dy}">${safeLine}</tspan>`;
       }).join('');

       const svgText = `<svg width="${svgWidth}" height="${svgHeight}"><style>.watermark { fill: rgba(255, 255, 255, 0.85); font-size: ${fontSize}px; font-weight: bold; font-family: 'Noto Sans CJK SC', 'Microsoft YaHei', sans-serif; text-anchor: ${textAnchor}; text-shadow: 2px 2px 4px rgba(0,0,0,0.8); }</style><text x="${startX}" y="${startY}" class="watermark">${tspans}</text></svg>`;

       pipeline = pipeline.composite([{ input: Buffer.from(svgText), gravity: 'center' }]);
    }

    if (format === 'bmp') {
        const { data: buffer, info } = await pipeline.toColorspace('srgb').raw().toBuffer({ resolveWithObject: true });
        const abgrBuffer = Buffer.alloc(buffer.length);
        for (let i = 0; i < buffer.length; i += 4) {
          const r = buffer[i]; const g = buffer[i + 1]; const b = buffer[i + 2]; const a = buffer[i + 3];
          abgrBuffer[i] = a; abgrBuffer[i + 1] = b; abgrBuffer[i + 2] = g; abgrBuffer[i + 3] = r; 
        }
        const rawData = { data: abgrBuffer, width: info.width, height: info.height };
        const bmpData = bmp.encode(rawData);
        fs.writeFileSync(outputPath, bmpData.data);
    } else {
        if (['jpeg', 'jpg'].includes(format)) {
             pipeline = pipeline.flatten({ background: '#ffffff' });
             pipeline = pipeline.jpeg({ quality: options.quality });
        } else if (format === 'png') { pipeline = pipeline.png();
        } else if (format === 'webp') { pipeline = pipeline.webp({ quality: options.quality });
        } else if (format === 'avif') { pipeline = pipeline.avif({ quality: options.quality });
        } else { pipeline = pipeline.toFormat(format); }
        await pipeline.toFile(outputPath);
    }

    incrementStats();
    const stats = fs.statSync(outputPath);
    console.log(`Processing complete: ${outputFilename}`);

    res.json({
      url: `/api/processed/${outputFilename}`,
      filename: outputFilename,
      size: stats.size
    });

  } catch (error) {
    console.error('Processing error details:', error);
    const msg = error.message.includes('unsupported image format') ? 'Input format corrupted or unsupported.' : error.message;
    res.status(500).json({ error: `Processing failed: ${msg}` });
  }
});

app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === 'LIMIT_FILE_SIZE') {
      return res.status(400).json({ error: 'File too large (Max 20MB)' });
    }
  }
  console.error('Unhandled server error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

import React, { useState, useEffect, useRef } from 'react';
import { StockAnalysisResult, Language } from '../types';

interface StockDashboardProps {
  lang: Language;
}

export const StockDashboard: React.FC<StockDashboardProps> = ({ lang }) => {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<StockAnalysisResult | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const t = {
    en: {
      title: "QUANTUM FINANCE ANALYZER",
      inputPlaceholder: "ENTER STOCK CODE (e.g., 600519)",
      analyze: "INITIATE ANALYSIS",
      analyzing: "COMPUTING...",
      trend: "TREND JUDGMENT",
      tech: "TECHNICAL ANALYSIS",
      strategy: "STRATEGY",
      risk: "RISK FACTORS",
      strong: "STRONG",
      volatile: "VOLATILE",
      weak: "WEAK",
      chartTitle: "30-DAY PRICE ACTION SIMULATION"
    },
    zh: {
      title: "量子金融分析仪",
      inputPlaceholder: "输入股票代码 (如 600519)",
      analyze: "开始分析",
      analyzing: "计算中...",
      trend: "当前趋势判断",
      tech: "技术面解读",
      strategy: "操作思路",
      risk: "风险提示",
      strong: "偏强",
      volatile: "震荡",
      weak: "偏弱",
      chartTitle: "30日资金流向模拟"
    }
  }[lang];

  const handleAnalyze = async () => {
    if (!code) return;
    setLoading(true);
    setData(null);

    try {
      const response = await fetch('/api/analyze-stock', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code })
      });
      const result = await response.json();

      // Artificial delay for "processing" effect
      setTimeout(() => {
        setData(result);
        setLoading(false);
      }, 1500);

    } catch (e) {
      console.error(e);
      setLoading(false);
    }
  };

  // Draw Chart
  useEffect(() => {
    if (!data || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Reset
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const prices = data.history.map(d => d.price);
    const min = Math.min(...prices) * 0.99;
    const max = Math.max(...prices) * 1.01;
    const range = max - min;

    const w = canvas.width;
    const h = canvas.height;
    const padding = 20;
    const stepX = (w - padding * 2) / (prices.length - 1);

    // Draw Grid
    ctx.strokeStyle = 'rgba(6, 182, 212, 0.1)';
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
        const y = padding + (i * (h - padding * 2)) / 4;
        ctx.moveTo(padding, y);
        ctx.lineTo(w - padding, y);
    }
    ctx.stroke();

    // Draw Line
    ctx.beginPath();
    ctx.lineWidth = 2;
    ctx.strokeStyle = data.changePercent >= 0 ? '#10b981' : '#ef4444'; // Green or Red

    prices.forEach((price, i) => {
        const x = padding + i * stepX;
        const y = h - (padding + ((price - min) / range) * (h - padding * 2));
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Draw Gradient Area
    ctx.lineTo(w - padding, h - padding);
    ctx.lineTo(padding, h - padding);
    ctx.closePath();
    const gradient = ctx.createLinearGradient(0, 0, 0, h);
    gradient.addColorStop(0, data.changePercent >= 0 ? 'rgba(16, 185, 129, 0.2)' : 'rgba(239, 68, 68, 0.2)');
    gradient.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = gradient;
    ctx.fill();

    // Draw Points
    ctx.fillStyle = '#fff';
    prices.forEach((price, i) => {
        if (i % 5 === 0 || i === prices.length - 1) { // Sparse points
            const x = padding + i * stepX;
            const y = h - (padding + ((price - min) / range) * (h - padding * 2));
            ctx.beginPath();
            ctx.arc(x, y, 2, 0, Math.PI * 2);
            ctx.fill();
        }
    });

  }, [data]);

  return (
    <div className="h-full flex flex-col items-center justify-center p-6 relative">
       {/* Background Decor */}
       <div className="absolute inset-0 pointer-events-none overflow-hidden">
          <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-purple-600/10 rounded-full blur-[100px] animate-pulse"></div>
          <div className="absolute bottom-1/4 right-1/4 w-64 h-64 bg-cyan-600/10 rounded-full blur-[80px]"></div>
       </div>

       <div className="max-w-4xl w-full z-10 space-y-8">
          <div className="text-center">
             <h2 className="text-4xl font-tech font-bold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-cyan-400 tracking-widest drop-shadow-[0_0_10px_rgba(168,85,247,0.5)]">
                {t.title}
             </h2>
             <div className="h-px w-64 mx-auto bg-gradient-to-r from-transparent via-purple-500 to-transparent mt-4"></div>
          </div>

          {/* Input Area */}
          <div className="flex gap-4 max-w-lg mx-auto bg-slate-900/80 p-2 border border-purple-500/30 backdrop-blur-md shadow-[0_0_20px_rgba(168,85,247,0.15)] clip-button">
             <input 
               type="text" 
               value={code}
               onChange={(e) => setCode(e.target.value)}
               placeholder={t.inputPlaceholder}
               className="flex-1 bg-transparent border-none text-white font-code px-4 focus:outline-none placeholder-slate-600 tracking-wider"
             />
             <button 
               onClick={handleAnalyze}
               disabled={loading}
               className="bg-purple-600 hover:bg-purple-500 text-white font-tech px-8 py-2 font-bold tracking-widest transition-all disabled:opacity-50 disabled:cursor-not-allowed"
             >
               {loading ? t.analyzing : t.analyze}
             </button>
          </div>

          {/* Results Area */}
          {data && (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in fade-in slide-in-from-bottom-10 duration-700">
                {/* Left: Stats & Chart */}
                <div className="space-y-6">
                   {/* Price Card */}
                   <div className="bg-slate-900/60 border border-slate-700 p-6 relative overflow-hidden group">
                      <div className="absolute top-0 right-0 p-2 text-[10px] text-slate-500 font-code">{data.code}</div>
                      <div className="flex items-end gap-4">
                         <span className="text-5xl font-code font-bold text-white tracking-tighter">{data.currentPrice.toFixed(2)}</span>
                         <span className={`text-lg font-code font-bold ${data.changePercent >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                            {data.changePercent >= 0 ? '+' : ''}{data.changePercent}%
                         </span>
                      </div>
                      {/* Decorative Lines */}
                      <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-slate-800 to-transparent"></div>
                   </div>

                   {/* Chart */}
                   <div className="bg-slate-900/60 border border-slate-700 p-4 relative">
                      <div className="text-[10px] text-cyan-500 font-tech mb-2 tracking-widest">{t.chartTitle}</div>
                      <canvas ref={canvasRef} width={400} height={200} className="w-full h-48 object-contain" />
                   </div>
                </div>

                {/* Right: AI Analysis Text */}
                <div className="space-y-4 font-code text-xs leading-relaxed">
                   {/* Trend */}
                   <div className="bg-slate-900/40 border-l-2 border-cyan-400 p-4">
                      <h4 className="text-cyan-400 font-bold mb-1 tracking-wider">{t.trend}</h4>
                      <div className="text-white text-lg font-tech uppercase">
                          {data.trend === 'STRONG' && <span className="text-green-400 drop-shadow-[0_0_5px_rgba(74,222,128,0.5)]">{t.strong}</span>}
                          {data.trend === 'VOLATILE' && <span className="text-yellow-400 drop-shadow-[0_0_5px_rgba(250,204,21,0.5)]">{t.volatile}</span>}
                          {data.trend === 'WEAK' && <span className="text-red-400 drop-shadow-[0_0_5px_rgba(248,113,113,0.5)]">{t.weak}</span>}
                      </div>
                   </div>

                   <div className="bg-slate-900/40 border-l-2 border-purple-400 p-4">
                      <h4 className="text-purple-400 font-bold mb-1 tracking-wider">{t.tech}</h4>
                      <p className="text-slate-300">{data.techAnalysis}</p>
                   </div>

                   <div className="bg-slate-900/40 border-l-2 border-blue-400 p-4">
                      <h4 className="text-blue-400 font-bold mb-1 tracking-wider">{t.strategy}</h4>
                      <p className="text-slate-300">{data.strategy}</p>
                   </div>

                   <div className="bg-slate-900/40 border-l-2 border-red-500 p-4">
                      <h4 className="text-red-500 font-bold mb-1 tracking-wider">{t.risk}</h4>
                      <p className="text-slate-300">{data.risks}</p>
                   </div>
                </div>
             </div>
          )}
       </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { StockDashboard } from './components/StockDashboard';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse, Language, RawPixelFormat } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: '',
  watermarkPosition: 'bottom-right',
  rawWidth: undefined,
  rawHeight: undefined,
  rawPixelFormat: 'uyvy' // default
};

type AppMode = 'image' | 'data';

function App() {
  const [lang, setLang] = useState<Language>('en');
  const [mode, setMode] = useState<AppMode>('image');
  const [dataUnlocked, setDataUnlocked] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');

  // Image Core States
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);
  const [totalProcessed, setTotalProcessed] = useState(0);

  const t = {
    en: {
      appTitle: "TUKUKU",
      sloganTitle: "IMAGE PROCESSOR",
      uploadFailed: "CRITICAL ERROR: UPLOAD FAILED",
      processFailed: "PROCESSING ERROR",
      processedSuccess: "RENDER_COMPLETE",
      preview: "VISUAL_FEED",
      noPreview: "NO VISUAL FEED FOR RAW DATA",
      originalSize: "INPUT_SIZE",
      newSize: "OUTPUT_SIZE",
      savings: "EFFICIENCY",
      startOver: "RESET_SYSTEM",
      download: "EXTRACT_DATA",
      serverDesc: "SECURE SERVER CONNECTION :: ESTABLISHED",
      status: "STATUS",
      coord: "COORD",
      auto: "AUTO",
      modeImage: "IMAGE_CORE",
      modeData: "DATA_CORE",
      enterPwd: "ENTER ACCESS CODE",
      unlock: "UNLOCK",
      accessDenied: "ACCESS DENIED: MODULE UNDER CONSTRUCTION"
    },
    zh: {
      appTitle: "图酷酷",
      sloganTitle: "图像处理器",
      uploadFailed: "严重错误：上传失败",
      processFailed: "处理错误",
      processedSuccess: "渲染完毕",
      preview: "视觉反馈",
      noPreview: "RAW 数据无视觉反馈",
      originalSize: "输入体积",
      newSize: "输出体积",
      savings: "效率提升",
      startOver: "重置系统",
      download: "提取数据",
      serverDesc: "安全连接 :: 已建立",
      status: "状态",
      coord: "尺寸",
      auto: "自动",
      modeImage: "图像核心",
      modeData: "数据核心",
      enterPwd: "输入访问密钥",
      unlock: "解锁",
      accessDenied: "访问拒绝：功能正在新增中"
    }
  }[lang];

  // Fetch stats on load
  useEffect(() => {
    fetch('/api/stats')
      .then(res => res.json())
      .then(data => {
        if (data.processedCount) setTotalProcessed(data.processedCount);
      })
      .catch(err => console.error("Failed to load stats", err));
  }, []);

  // Helper to guess pixel format from extension
  const getFormatFromExt = (filename: string): RawPixelFormat => {
      const lower = filename.toLowerCase();
      if (lower.endsWith('.uyvy')) return 'uyvy';
      if (lower.endsWith('.nv21')) return 'nv21';
      if (lower.endsWith('.rgba')) return 'rgba';
      if (lower.endsWith('.bgra')) return 'bgra';
      if (lower.endsWith('.rgb')) return 'rgb';
      if (lower.endsWith('.bgr')) return 'bgr';
      return 'uyvy'; 
  };

  const isRawFormat = (filename: string) => {
      const exts = ['.uyvy', '.yuv', '.nv21', '.raw', '.rgb', '.bgr', '.bgra', '.rgba', '.bin'];
      return exts.some(ext => filename.toLowerCase().endsWith(ext));
  };

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errorMessage = `${t.uploadFailed} (${response.status})`;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
          errorMessage = `${t.uploadFailed}: ${response.statusText || response.status}`;
        }
        throw new Error(errorMessage);
      }

      const data: UploadResponse = await response.json();
      setCurrentFile(data);

      const suggestedFormat = getFormatFromExt(data.originalName);
      const isRaw = isRawFormat(data.originalName);

      setOptions({
        ...defaultOptions,
        format: ImageFormat.ORIGINAL,
        width: data.width || null,
        height: data.height || null,
        rawWidth: isRaw ? (data.width || 1920) : undefined,
        rawHeight: isRaw ? (data.height || 1080) : undefined,
        rawPixelFormat: suggestedFormat
      });
    } catch (error: any) {
      console.error(error);
      alert(error.message || t.uploadFailed);
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) {
        let errorMessage = t.processFailed;
        try {
          const errorData = await response.json();
          if (errorData.error) errorMessage = errorData.error;
        } catch (e) {
           errorMessage = `${t.processFailed}: ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }

      const data: ProcessResponse = await response.json();

      await new Promise((resolve) => {
        const img = new Image();
        img.src = data.url;
        img.onload = resolve;
        img.onerror = resolve; 
      });

      setResult(data);
      setTotalProcessed(prev => prev + 1);

    } catch (error: any) {
      console.error(error);
      alert(error.message || t.processFailed);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setOptions(defaultOptions);
  };

  const getBitDepthLabel = (depth?: string) => {
    if (!depth) return null;
    if (depth === 'uchar') return null; 
    if (depth === 'ushort' || depth === 'short') return '16-BIT';
    if (depth === 'float') return '32-BIT FLOAT';
    if (depth === 'uint' || depth === 'int') return '32-BIT INT';
    return depth.toUpperCase();
  };

  const toggleLang = () => {
    setLang(prev => prev === 'en' ? 'zh' : 'en');
  };

  const handleModeSwitch = (newMode: AppMode) => {
    if (newMode === 'data' && !dataUnlocked) {
      setShowPasswordModal(true);
    } else {
      setMode(newMode);
    }
  };

  const handleUnlock = () => {
    if (passwordInput === '666888') {
      setDataUnlocked(true);
      setShowPasswordModal(false);
      setMode('data');
      setPasswordInput('');
    } else {
      alert(t.accessDenied);
      setShowPasswordModal(false);
      setPasswordInput('');
    }
  };

  return (
    <div className="flex flex-col h-full bg-transparent text-slate-300 font-sans selection:bg-cyan-500/30 selection:text-cyan-100">

      {/* Password Modal */}
      {showPasswordModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
           <div className="bg-slate-900 border border-cyan-500/50 p-8 max-w-sm w-full shadow-[0_0_50px_rgba(6,182,212,0.3)] relative overflow-hidden">
               <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-500 via-purple-500 to-cyan-500 animate-pulse"></div>
               <h3 className="text-xl font-tech text-cyan-400 mb-6 text-center tracking-widest">{t.enterPwd}</h3>
               <input 
                 type="password" 
                 value={passwordInput}
                 onChange={(e) => setPasswordInput(e.target.value)}
                 className="w-full bg-black border border-slate-600 text-white px-4 py-2 font-code text-center tracking-[0.5em] mb-6 focus:outline-none focus:border-cyan-500"
                 autoFocus
                 onKeyDown={(e) => e.key === 'Enter' && handleUnlock()}
               />
               <div className="flex gap-4">
                  <button onClick={() => setShowPasswordModal(false)} className="flex-1 py-2 font-code text-slate-500 hover:text-white border border-transparent hover:border-slate-500">CANCEL</button>
                  <button onClick={handleUnlock} className="flex-1 py-2 bg-cyan-600 hover:bg-cyan-500 text-white font-tech tracking-wider clip-button">{t.unlock}</button>
               </div>
           </div>
        </div>
