export interface OHLC {
  date: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  ma5?: number;
  ma10?: number;
  ma20?: number;
}

export interface StockAnalysisResult {
  code: string;
  market: string;
  name: string;
  currentPrice: number;
  changeAmount: number;
  changePercent: number;
  // Fundamental
  pe: number;
  pb: number;
  turnoverRate: number;
  amplitude: number;
  // Technical Stats
  trend: 'STRONG' | 'VOLATILE' | 'WEAK';
  support: number;
  resistance: number;
  sentiment: number; // 0-100
  // Textual Analysis
  techAnalysis: string;
  strategyAdvice: {
    shortTerm: string; // 打板选手/短线
    longTerm: string;  // 价值投资
    trendFollower: string; // 均线/趋势
  };
  risks: string[];
  history: OHLC[];
}

