      refresh: "同步实时",
      analyzing: "正在检索数据...",
      refreshing: "同步中...",
      metrics: "实时行情指标",
      pe: "市盈率", pb: "市净率", turnover: "换手率", amp: "振幅",
      strategy: "AI 投资策略建议",
      shortTerm: "短线 / 打板选手",
      longTerm: "长线 / 价值投资",
      trend: "趋势 / 均线跟踪",
      risk: "风险预警",
      sentiment: "多空情绪指数",
      chartTitle: "180日 K线走势 (实时锚定模拟)",
      support: "支撑位", resistance: "阻力位",
      realtimeStatus: "联网实时查询",
      fallbackStatus: "由于频率限制进入离线模式",
      startTime: "起始时间",
      endTime: "结束时间",
      lastUpdate: "最后更新"
    }
  }[lang];

  const handleAnalyze = async (isDeepRefresh = false) => {
    if (!code) return;
    if (isDeepRefresh) setRefreshing(true); else setLoading(true);

    try {
      const response = await fetch('/api/analyze-stock', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, forceSearch: isDeepRefresh })
      });

      if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || 'Server Error');
      }
      const result = await response.json();
      setData(result);
    } catch (e: any) {
      console.error("Analysis Error:", e);
      alert(`Terminal Error: ${e.message}`);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    if (!data || !mainCanvasRef.current) return;
    const canvas = mainCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    const kH = h * 0.85; 
    const padding = 60;
    ctx.clearRect(0, 0, w, h);

    const hist = data.history;
    const maxP = Math.max(...hist.map(d => d.high)) * 1.02;
    const minP = Math.min(...hist.map(d => d.low)) * 0.98;
    const range = maxP - minP;
    const stepX = (w - padding * 2) / (hist.length || 1);
    const getY = (p: number) => padding + (1 - (p - minP) / (range || 1)) * (kH - padding * 2);

    // Draw Gridlines with Price Labels
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.lineWidth = 1;
    ctx.font = '10px JetBrains Mono, monospace';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    ctx.textAlign = 'right';

    for (let i = 0; i < 6; i++) {
       const gridY = padding + (i / 5) * (kH - padding * 2);
       const price = maxP - (i / 5) * range;
       ctx.beginPath();
       ctx.moveTo(padding, gridY);
       ctx.lineTo(w - padding, gridY);
       ctx.stroke();
       ctx.fillText(price.toFixed(3), padding - 10, gridY + 3);
    }

    // Draw Candles
    hist.forEach((d, i) => {
      const x = padding + i * stepX;
      const isUp = d.close >= d.open;
      const color = isUp ? '#ef4444' : '#22c55e';
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;

      // Shadow
      ctx.beginPath();
      ctx.moveTo(x + stepX*0.35, getY(d.high));
      ctx.lineTo(x + stepX*0.35, getY(d.low));
      ctx.stroke();

      // Body
      ctx.fillStyle = color;
      const oY = getY(d.open);
      const cY = getY(d.close);
      ctx.fillRect(x, Math.min(oY, cY), stepX * 0.7, Math.max(1, Math.abs(oY - cY)));
    });

    // Draw Moving Averages
    const drawMA = (key: 'ma5'|'ma10'|'ma20', color: string) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      let first = true;
      hist.forEach((d, i) => {
        const val = (d as any)[key];
        if (val) {
          const x = padding + i * stepX + stepX * 0.35;
          const y = getY(val);
          if (first) { ctx.moveTo(x, y); first = false; }
          else ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    };
    drawMA('ma5', '#fef08a'); drawMA('ma10', '#f472b6'); drawMA('ma20', '#60a5fa');

    // Draw X-Axis Date Labels
    if (hist.length > 0) {
       ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
       ctx.font = '10px JetBrains Mono, monospace';

       // Start Date
       ctx.textAlign = 'left';
       ctx.fillText(`${t.startTime}: ${hist[0].date}`, padding, kH + 25);

       // Mid Date (estimated)
       const mid = Math.floor(hist.length / 2);
       ctx.textAlign = 'center';
       ctx.fillText(hist[mid].date, padding + mid * stepX, kH + 25);

       // End Date
       ctx.textAlign = 'right';
       ctx.fillText(`${t.endTime}: ${hist[hist.length-1].date}`, w - padding, kH + 25);
    }
  }, [data, lang]);

  return (
    <div className="h-full flex flex-col p-6 relative custom-scrollbar overflow-y-auto">
      <div className="max-w-6xl w-full mx-auto space-y-6 pb-12">
        <div className="text-center">
