const STATS_FILE = path.join(DATA_DIR, 'stats.json');

[UPLOAD_DIR, PROCESSED_DIR, DATA_DIR].forEach(dir => {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
});

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => cb(null, uuidv4() + path.extname(file.originalname))
});
const upload = multer({ storage });

function getStats() {
  try {
    if (!fs.existsSync(STATS_FILE)) {
      const initial = { processedCount: 0 };
      fs.writeFileSync(STATS_FILE, JSON.stringify(initial));
      return initial;
    }
    const content = fs.readFileSync(STATS_FILE, 'utf8').trim();
    return content ? JSON.parse(content) : { processedCount: 0 };
  } catch (e) { return { processedCount: 0 }; }
}

function incrementStats() {
  const stats = getStats();
  stats.processedCount += 1;
  fs.writeFileSync(STATS_FILE, JSON.stringify(stats));
}

app.get('/api/stats', (req, res) => res.json(getStats()));

app.post('/api/upload', upload.single('image'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  try {
    const metadata = await sharp(req.file.path).metadata();
    res.json({
      id: path.basename(req.file.filename, path.extname(req.file.filename)),
      filename: req.file.filename,
      url: `/api/files/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: metadata.width,
      height: metadata.height,
      format: metadata.format,
      depth: metadata.depth
    });
  } catch (err) {
    res.json({ id: uuidv4(), filename: req.file.filename, url: `/api/files/${req.file.filename}`, originalName: req.file.originalname, size: req.file.size });
  }
});

app.use('/api/files', express.static(UPLOAD_DIR));
app.use('/api/processed', express.static(PROCESSED_DIR));

app.post('/api/process', async (req, res) => {
  const { id, options } = req.body;
  const files = fs.readdirSync(UPLOAD_DIR);
  const fileName = files.find(f => f.startsWith(id));
  if (!fileName) return res.status(404).json({ error: 'File not found' });

  const inputPath = path.join(UPLOAD_DIR, fileName);
  const outFilename = `processed_${uuidv4()}.${options.format === 'original' ? 'jpg' : options.format}`;
  const outputPath = path.join(PROCESSED_DIR, outFilename);

  try {
    let pipeline = sharp(inputPath);
    if (options.rotate) pipeline = pipeline.rotate(options.rotate);
    if (options.flipX) pipeline = pipeline.flop();
    if (options.flipY) pipeline = pipeline.flip();
    if (options.grayscale) pipeline = pipeline.grayscale();
    if (options.blur) pipeline = pipeline.blur(options.blur);
    if (options.sharpen) pipeline = pipeline.sharpen();
    if (options.width || options.height) pipeline = pipeline.resize(options.width, options.height, { fit: options.resizeMode || 'cover' });

    if (options.format === 'png') pipeline = pipeline.png();
    else if (options.format === 'webp') pipeline = pipeline.webp({ quality: options.quality });
    else pipeline = pipeline.jpeg({ quality: options.quality });

    await pipeline.toFile(outputPath);
    incrementStats();
    res.json({ url: `/api/processed/${outFilename}`, filename: outFilename, size: fs.statSync(outputPath).size });
  } catch (err) { res.status(500).json({ error: 'Processing failed' }); }
});

function extractJson(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { throw new Error("JSON_PARSE_ERROR"); }
    }
    throw e;
  }
}

app.post('/api/analyze-stock', async (req, res) => {
  const { code, forceSearch } = req.body;
  if (!process.env.API_KEY) return res.status(500).json({ error: "API_KEY_MISSING" });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelName = 'gemini-3-flash-preview';

  const prompt = `You are a Quant Analyst specialized in China Market ETFs.
  Analyze Ticker: "${code}".

  VERIFICATION RULES:
  1. Use Google Search to get the EXACT name, current price, premium/discount rate, and 52-week price range.
  2. If code is 513090, it is the '易方达中证香港证券投资主题ETF'. Its underlying index is the CSI Hong Kong Securities Index.
  3. Identify if it's an ETF or a Stock. If ETF, find the 'Premium/Discount Rate' (折溢价率).

  OUTPUT JSON ONLY:
  {
    "name": "Full Name",
    "market": "SH/SZ/HK/US/ETF",
    "currentPrice": number,
    "changePercent": number,
    "premiumRate": number, (Percentage, e.g. 0.5 means 0.5% premium)
    "pe": number,
    "pb": number,
    "volatility": "HIGH|MED|LOW",
    "high52": number,
    "low52": number,
    "sentiment": number, (0-100)
    "strategyAdvice": {
      "shortTerm": "Advice for intraday/scalping",
      "longTerm": "Advice for value holding",
      "trendFollower": "MA/Technical breakout view"
    },
    "risks": ["Risk 1", "Risk 2"]
  }`;

  try {
    const result = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: { 
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }]
      }
    });

    const data = extractJson(result.text);
    data.lastUpdated = new Date().toISOString();
    data.isRealtime = true;

    // Use 52-week anchors to generate a much more realistic history
    const history = [];
    const DAYS = 180;
    const high = data.high52 || data.currentPrice * 1.2;
    const low = data.low52 || data.currentPrice * 0.8;
    const startPrice = (high + low) / 2;

    let p = startPrice;
    for (let i = 0; i < DAYS; i++) {
      // Logic to drift towards currentPrice at the end of 180 days
      const targetDrift = (data.currentPrice - p) / (DAYS - i);
      const randomVol = (Math.random() - 0.5) * (p * 0.03);
      const close = p + targetDrift + randomVol;

      history.push({
        date: new Date(Date.now() - (DAYS - i) * 86400000).toISOString().split('T')[0],
        open: parseFloat(p.toFixed(3)),
        high: parseFloat((Math.max(p, close) * 1.008).toFixed(3)),
        low: parseFloat((Math.min(p, close) * 0.992).toFixed(3)),
        close: parseFloat(close.toFixed(3)),
        volume: Math.floor(2000000 + Math.random() * 8000000)
      });
      p = close;
    }

    // Ensure the last close is exactly the current price
    history[history.length - 1].close = data.currentPrice;

    for (let i = 0; i < history.length; i++) {
        const ma = (d) => i < d - 1 ? null : parseFloat((history.slice(i - d + 1, i + 1).reduce((a, b) => a + b.close, 0) / d).toFixed(3));
        history[i].ma5 = ma(5);
        history[i].ma10 = ma(10);
        history[i].ma20 = ma(20);
    }

    return res.json({ ...data, history, code });

  } catch (err) {
    console.error("Analysis Failure:", err);
    res.status(500).json({ error: "ANALYSIS_FAILED", message: err.message });
  }
});

app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

import React, { useState, useEffect, useRef } from 'react';
import { StockAnalysisResult, Language, OHLC } from '../types';

interface ExtendedStockResult extends StockAnalysisResult {
  isRealtime?: boolean;
  lastUpdated?: string;
  premiumRate?: number;
  high52?: number;
  low52?: number;
}

interface StockDashboardProps {
  lang: Language;
}

export const StockDashboard: React.FC<StockDashboardProps> = ({ lang }) => {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [data, setData] = useState<ExtendedStockResult | null>(null);
  const mainCanvasRef = useRef<HTMLCanvasElement>(null);

  const t = {
    en: {
      title: "QUANTUM TRADING TERMINAL",
      inputPlaceholder: "STOCK CODE (e.g. 513090, 00700, TSLA)",
      analyze: "INITIATE SCAN",
      refresh: "SYNC_LIVE",
      analyzing: "SEARCHING DATA...",
      refreshing: "SYNCING...",
      metrics: "REAL-TIME METRICS",
      pe: "P/E", pb: "P/B", premium: "Premium", amp: "Amplitude",
      strategy: "AI STRATEGY ANALYSIS",
      shortTerm: "Short-term/Scalp",
      longTerm: "Value/Long-term",
      trend: "Trend/MA",
      risk: "RISK PROFILE",
      sentiment: "SENTIMENT",
      chartTitle: "180-DAY K-LINE (GROUNDED SIMULATION)",
      support: "Support", resistance: "Resistance",
      realtimeStatus: "LIVE_SEARCH",
      fallbackStatus: "INTERNAL_KNOWLEDGE",
      startTime: "T-START",
      endTime: "T-NOW",
      high52: "52W HIGH",
      low52: "52W LOW"
    },
    zh: {
      title: "量子金融交易终端",
      inputPlaceholder: "输入股票代码 (如 513090, 00700, TSLA)",
      analyze: "开启扫描",
      refresh: "同步实时",
      analyzing: "正在检索数据...",
      refreshing: "同步中...",
      metrics: "实时量化指标",
      pe: "市盈率", pb: "市净率", premium: "折溢价率", amp: "振幅",
      strategy: "AI 投资策略建议",
      shortTerm: "短线 / 打板选手",
      longTerm: "长线 / 价值投资",
      trend: "趋势 / 均线跟踪",
      risk: "风险预警",
      sentiment: "多空情绪指数",
      chartTitle: "180日 K线走势 (实时锚定模拟)",
      support: "支撑位", resistance: "阻力位",
      realtimeStatus: "联网实时数据",
      fallbackStatus: "离线分析模式",
      startTime: "起始时间",
      endTime: "结束时间",
      high52: "52周最高",
      low52: "52周最低"
    }
  }[lang];

  const handleAnalyze = async (isDeepRefresh = false) => {
    if (!code) return;
    if (isDeepRefresh) setRefreshing(true); else setLoading(true);

    try {
      const response = await fetch('/api/analyze-stock', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code, forceSearch: isDeepRefresh || true })
      });

      if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || 'Server Error');
      }
      const result = await response.json();
      setData(result);
    } catch (e: any) {
      console.error("Analysis Error:", e);
      alert(`Terminal Error: ${e.message}`);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    if (!data || !mainCanvasRef.current) return;
    const canvas = mainCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    const kH = h * 0.82; 
    const padding = 65;
    ctx.clearRect(0, 0, w, h);

    const hist = data.history;
    const maxP = Math.max(...hist.map(d => d.high)) * 1.01;
    const minP = Math.min(...hist.map(d => d.low)) * 0.99;
    const range = maxP - minP;
    const stepX = (w - padding * 2) / (hist.length || 1);
    const getY = (p: number) => padding + (1 - (p - minP) / (range || 1)) * (kH - padding * 2);

    // Draw Gridlines with Precise Price Labels
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
    ctx.lineWidth = 1;
    ctx.font = '10px JetBrains Mono, monospace';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.25)';
    ctx.textAlign = 'right';

    for (let i = 0; i < 7; i++) {
       const gridY = padding + (i / 6) * (kH - padding * 2);
       const price = maxP - (i / 6) * range;
       ctx.beginPath();
       ctx.moveTo(padding, gridY);
       ctx.lineTo(w - padding, gridY);
       ctx.stroke();
       ctx.fillText(price.toFixed(3), padding - 10, gridY + 3);
    }

    // Draw Candles
    hist.forEach((d, i) => {
      const x = padding + i * stepX;
      const isUp = d.close >= d.open;
      const color = isUp ? '#ef4444' : '#22c55e';
      ctx.strokeStyle = color;

      // Shadow
      ctx.beginPath();
      ctx.moveTo(x + stepX*0.35, getY(d.high));
      ctx.lineTo(x + stepX*0.35, getY(d.low));
      ctx.stroke();

      // Body
      ctx.fillStyle = color;
      const oY = getY(d.open);
      const cY = getY(d.close);
      ctx.fillRect(x, Math.min(oY, cY), stepX * 0.7, Math.max(1, Math.abs(oY - cY)));
    });

    // Draw Moving Averages
    const drawMA = (key: 'ma5'|'ma10'|'ma20', color: string) => {
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      let first = true;
      hist.forEach((d, i) => {
        const val = (d as any)[key];
        if (val) {
          const x = padding + i * stepX + stepX * 0.35;
          const y = getY(val);
          if (first) { ctx.moveTo(x, y); first = false; }
          else ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    };
    drawMA('ma5', '#fef08a'); drawMA('ma10', '#f472b6'); drawMA('ma20', '#60a5fa');

    // Draw X-Axis Date Labels
    if (hist.length > 0) {
       ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
       ctx.textAlign = 'left';
       ctx.fillText(`${t.startTime}: ${hist[0].date}`, padding, kH + 25);
       ctx.textAlign = 'right';
       ctx.fillText(`${t.endTime}: ${hist[hist.length-1].date}`, w - padding, kH + 25);
    }
  }, [data, lang]);

  return (
    <div className="h-full flex flex-col p-6 relative custom-scrollbar overflow-y-auto bg-slate-950/20">
      <div className="max-w-6xl w-full mx-auto space-y-6 pb-12">
        <div className="text-center">
          <h2 className="text-4xl font-tech font-bold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-cyan-400 uppercase tracking-widest">{t.title}</h2>
          <div className="flex justify-center gap-4 mt-2">
            <p className="text-[10px] text-slate-500 font-code uppercase tracking-[0.2em]">Data Engine :: Grounding Enabled</p>
          </div>
        </div>

        <div className="flex gap-4 max-w-2xl mx-auto bg-slate-900/80 p-1.5 border border-cyan-500/30 backdrop-blur-xl clip-button">
          <input 
            type="text" 
            value={code} 
            onChange={(e) => setCode(e.target.value)} 
            placeholder={t.inputPlaceholder} 
            className="flex-1 bg-transparent border-none text-white font-code px-5 focus:outline-none text-lg uppercase" 
            onKeyDown={(e) => e.key === 'Enter' && handleAnalyze(false)} 
          />
          <button 
            onClick={() => handleAnalyze(false)} 
            disabled={loading || refreshing} 
            className="bg-cyan-600 hover:bg-cyan-500 text-white font-tech px-10 py-3 disabled:opacity-50 font-bold transition-all relative overflow-hidden group"
          >
            <span className="relative z-10">{loading ? t.analyzing : t.analyze}</span>
          </button>
        </div>

        {data && (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="lg:col-span-3 space-y-6">
              <div className="bg-slate-900/60 border border-slate-800 p-8 flex flex-wrap items-center justify-between relative backdrop-blur-sm overflow-hidden">
                <div className={`absolute top-0 left-0 w-2 h-full ${data.isRealtime ? 'bg-cyan-500' : 'bg-amber-500'}`}></div>

                <div className="absolute top-2 right-4 flex items-center gap-4">
                    <button onClick={() => handleAnalyze(true)} disabled={refreshing} className="flex items-center gap-1.5 px-3 py-1 bg-slate-800 border border-slate-700 text-[10px] font-tech text-cyan-400 hover:bg-slate-700 transition-all">
                        {refreshing ? t.refreshing : t.refresh}
                    </button>
                    <div className="flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full ${data.isRealtime ? 'bg-cyan-400 animate-pulse' : 'bg-amber-500'}`}></span>
                        <span className="text-[9px] font-code uppercase tracking-tighter text-cyan-400">
                            {data.isRealtime ? t.realtimeStatus : t.fallbackStatus}
                        </span>
                    </div>
                </div>

                <div>
                  <div className="flex items-center gap-3">
                    <span className="text-white font-tech text-2xl font-bold">{data.name}</span>
                    <span className="text-cyan-400 bg-cyan-500/10 px-2 py-0.5 text-[10px] font-code border border-cyan-500/30">{data.market}</span>
                  </div>
                  <div className="flex gap-4 mt-4 items-baseline">
                    <span className="text-6xl font-code font-bold text-white tabular-nums">{(data.currentPrice || 0).toFixed(3)}</span>
                    <div className={`font-code font-bold ${(data.changePercent || 0) >= 0 ? 'text-red-500' : 'text-green-500'}`}>
                      <span className="text-2xl ml-2">({data.changePercent || 0}%)</span>
                    </div>
                  </div>
                </div>

                <div className="flex gap-8">
                  <div className="text-right">
                    <div className="text-xs text-slate-500 font-tech uppercase">{t.premium}</div>
                    <div className={`text-2xl font-code font-bold ${Math.abs(data.premiumRate || 0) > 1 ? 'text-red-400' : 'text-cyan-400'}`}>
                       {data.premiumRate !== undefined ? `${data.premiumRate}%` : '--'}
                    </div>
                  </div>
                  <div className="text-right hidden sm:block">
                    <div className="text-xs text-slate-500 font-tech uppercase">{t.sentiment}</div>
                    <div className="text-4xl font-code font-bold text-purple-400">{data.sentiment}%</div>
                  </div>
                </div>
              </div>

              <div className="bg-black/60 border border-slate-800 p-4 shadow-2xl relative">
                <div className="absolute top-4 left-6 text-[10px] font-code text-slate-600 uppercase z-10">{t.chartTitle}</div>
                <canvas ref={mainCanvasRef} width={1000} height={450} className="w-full h-[380px]" />
                <div className="absolute bottom-4 left-6 flex gap-4">
                   <div className="flex items-center gap-1.5"><div className="w-3 h-0.5 bg-[#fef08a]"></div><span className="text-[9px] font-code text-slate-500">MA5</span></div>
                   <div className="flex items-center gap-1.5"><div className="w-3 h-0.5 bg-[#f472b6]"></div><span className="text-[9px] font-code text-slate-500">MA10</span></div>
                   <div className="flex items-center gap-1.5"><div className="w-3 h-0.5 bg-[#60a5fa]"></div><span className="text-[9px] font-code text-slate-500">MA20</span></div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                 {[
                   { title: t.shortTerm, color: 'cyan', text: data.strategyAdvice.shortTerm },
                   { title: t.longTerm, color: 'purple', text: data.strategyAdvice.longTerm },
                   { title: t.trend, color: 'blue', text: data.strategyAdvice.trendFollower }
                 ].map(s => (
                   <div key={s.title} className="bg-slate-900/80 p-5 border border-slate-800 clip-button group">
                      <h5 className={`text-${s.color}-400 text-xs font-tech mb-3 uppercase`}>{s.title}</h5>
                      <p className="text-[12px] text-slate-300 leading-relaxed font-code">{s.text}</p>
                   </div>
                 ))}
              </div>
            </div>

            <div className="space-y-6">
               <div className="bg-slate-900/80 border border-slate-800 p-6">
                  <h4 className="text-[11px] font-tech font-bold text-slate-500 mb-6 uppercase border-b border-slate-800 pb-2 tracking-widest">{t.metrics}</h4>
                  <div className="space-y-5">
                     {[
                       { label: t.pe, val: data.pe }, { label: t.pb, val: data.pb },
                       { label: t.high52, val: data.high52 }, { label: t.low52, val: data.low52 }
                     ].map(item => (
                       <div key={item.label} className="flex justify-between items-end border-b border-slate-800/50 pb-1">
                          <span className="text-[11px] text-slate-400 font-code uppercase">{item.label}</span>
                          <span className="text-lg font-code text-white font-bold">{item.val || '--'}</span>
                       </div>
                     ))}
                  </div>
               </div>

               <div className="bg-red-900/10 border border-red-900/30 p-6">
                  <h4 className="text-[11px] font-tech font-bold text-red-500 mb-4 uppercase tracking-widest">{t.risk}</h4>
                  <ul className="space-y-3">
                     {data.risks.map((r, i) => (
                       <li key={i} className="text-[12px] text-red-200/70 font-code flex items-start gap-3">
                          <span className="mt-1.5 w-1.5 h-1.5 bg-red-500 shrink-0 shadow-[0_0_5px_red]"></span>{r}
                       </li>
                     ))}
                  </ul>
               </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import express from 'express';
import multer from 'multer';
import sharp from 'sharp';
import cors from 'cors';
import fs from 'fs';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { fileURLToPath } from 'url';
import { GoogleGenAI } from "@google/genai";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

const UPLOAD_DIR = path.join(__dirname, 'uploads');
const PROCESSED_DIR = path.join(__dirname, 'processed');
const DATA_DIR = path.join(__dirname, 'data');
const STATS_FILE = path.join(DATA_DIR, 'stats.json');

[UPLOAD_DIR, PROCESSED_DIR, DATA_DIR].forEach(dir => {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
});

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => cb(null, uuidv4() + path.extname(file.originalname))
});
const upload = multer({ storage });

function getStats() {
  try {
    if (!fs.existsSync(STATS_FILE)) {
      const initial = { processedCount: 0 };
      fs.writeFileSync(STATS_FILE, JSON.stringify(initial));
      return initial;
    }
    const content = fs.readFileSync(STATS_FILE, 'utf8').trim();
    return content ? JSON.parse(content) : { processedCount: 0 };
  } catch (e) { return { processedCount: 0 }; }
}

function incrementStats() {
  const stats = getStats();
  stats.processedCount += 1;
  fs.writeFileSync(STATS_FILE, JSON.stringify(stats));
}

app.get('/api/stats', (req, res) => res.json(getStats()));

app.post('/api/upload', upload.single('image'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  try {
    const metadata = await sharp(req.file.path).metadata();
    res.json({
      id: path.basename(req.file.filename, path.extname(req.file.filename)),
      filename: req.file.filename,
      url: `/api/files/${req.file.filename}`,
      originalName: req.file.originalname,
      size: req.file.size,
      width: metadata.width,
      height: metadata.height,
      format: metadata.format,
      depth: metadata.depth
    });
  } catch (err) {
    res.json({ id: uuidv4(), filename: req.file.filename, url: `/api/files/${req.file.filename}`, originalName: req.file.originalname, size: req.file.size });
  }
});

app.use('/api/files', express.static(UPLOAD_DIR));
app.use('/api/processed', express.static(PROCESSED_DIR));

app.post('/api/process', async (req, res) => {
  const { id, options } = req.body;
  const files = fs.readdirSync(UPLOAD_DIR);
  const fileName = files.find(f => f.startsWith(id));
  if (!fileName) return res.status(404).json({ error: 'File not found' });

  const inputPath = path.join(UPLOAD_DIR, fileName);
  const outFilename = `processed_${uuidv4()}.${options.format === 'original' ? 'jpg' : options.format}`;
  const outputPath = path.join(PROCESSED_DIR, outFilename);

  try {
    let pipeline = sharp(inputPath);
    if (options.rotate) pipeline = pipeline.rotate(options.rotate);
    if (options.flipX) pipeline = pipeline.flop();
    if (options.flipY) pipeline = pipeline.flip();
    if (options.grayscale) pipeline = pipeline.grayscale();
    if (options.blur) pipeline = pipeline.blur(options.blur);
    if (options.sharpen) pipeline = pipeline.sharpen();
    if (options.width || options.height) pipeline = pipeline.resize(options.width, options.height, { fit: options.resizeMode || 'cover' });

    if (options.format === 'png') pipeline = pipeline.png();
    else if (options.format === 'webp') pipeline = pipeline.webp({ quality: options.quality });
    else pipeline = pipeline.jpeg({ quality: options.quality });

    await pipeline.toFile(outputPath);
    incrementStats();
    res.json({ url: `/api/processed/${outFilename}`, filename: outFilename, size: fs.statSync(outputPath).size });
  } catch (err) { res.status(500).json({ error: 'Processing failed' }); }
});

function extractJson(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (e2) { throw new Error("JSON_PARSE_ERROR"); }
    }
    throw e;
  }
}

app.post('/api/analyze-stock', async (req, res) => {
  const { code, forceSearch } = req.body;
  if (!process.env.API_KEY) return res.status(500).json({ error: "API_KEY_MISSING" });

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelName = 'gemini-3-flash-preview';

  const prompt = `You are a Professional Quantitative Analyst. 
  Task: Identify and analyze Ticker "${code}".

  CRITICAL MAPPING HINTS:
  - If code is "513090", it is definitively "易方达中证香港证券投资主题ETF" (E Fund HK Securities ETF).
  - If code starts with "513", "510", "159", it is likely an ETF.

  ANALYSIS PROTOCOL:
  1. Use Google Search to get: Real-time price, Change%, Premium/Discount Rate (for ETFs), 52-Week High/Low, Turnover, and Volume.
  2. For 513090, specifically check the performance of the underlying 'CSI Hong Kong Securities Index'.
  3. Determine the "Sentiment Score" based on recent news and technical indicators.

  OUTPUT JSON ONLY:
  {
    "name": "Official Full Name",
    "market": "SH/SZ/HK/US/ETF",
    "currentPrice": number,
    "changePercent": number,
    "premiumRate": number,
    "pe": number,
    "pb": number,
    "high52": number,
    "low52": number,
    "turnover": number,
    "sentiment": number,
    "trendDescription": "Brief description of 180-day trend",
    "strategyAdvice": {
      "shortTerm": "Advice",
      "longTerm": "Advice",
      "trendFollower": "Advice"
    },
    "risks": ["Risk 1", "Risk 2"]
  }`;

  try {
    const result = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: { 
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }]
      }
    });

    const data = extractJson(result.text);
    data.lastUpdated = new Date().toISOString();
    data.isRealtime = !!result.candidates?.[0]?.groundingMetadata;

    // --- REFINED K-LINE GENERATION ALGORITHM ---
    const history = [];
    const DAYS = 180;
    const high = data.high52 || data.currentPrice * 1.15;
    const low = data.low52 || data.currentPrice * 0.85;

    // We simulate from 180 days ago towards the current price
    // We use a random walk with mean reversion to 52w average to keep it realistic
    const avg52 = (high + low) / 2;
    let p = avg52; // Start from the middle point 6 months ago

    for (let i = 0; i < DAYS; i++) {
      // Logic: Gradually drift p towards data.currentPrice
      const remainingDays = DAYS - i;
      const drift = (data.currentPrice - p) / remainingDays;
      const volatility = p * 0.015; // 1.5% daily vol
      const change = drift + (Math.random() - 0.5) * volatility;

      const close = Math.max(low * 0.98, Math.min(high * 1.02, p + change));

      history.push({
        date: new Date(Date.now() - (DAYS - i) * 86400000).toISOString().split('T')[0],
        open: parseFloat(p.toFixed(3)),
        high: parseFloat((Math.max(p, close) * (1 + Math.random() * 0.005)).toFixed(3)),
        low: parseFloat((Math.min(p, close) * (1 - Math.random() * 0.005)).toFixed(3)),
        close: parseFloat(close.toFixed(3)),
        volume: Math.floor(1000000 + Math.random() * 5000000)
      });
      p = close;
    }

    // Final candle must match current price
    history[history.length - 1].close = data.currentPrice;

    // MA Calculations
    for (let i = 0; i < history.length; i++) {
        const ma = (d) => i < d - 1 ? null : parseFloat((history.slice(i - d + 1, i + 1).reduce((a, b) => a + b.close, 0) / d).toFixed(3));
        history[i].ma5 = ma(5);
        history[i].ma10 = ma(10);
        history[i].ma20 = ma(20);
    }

    return res.json({ ...data, history, code });

  } catch (err) {
    console.error("Analysis Failed:", err);
    res.status(500).json({ error: "ANALYSIS_FAILED", message: err.message });
  }
});

