      refresh: "强制同步",
      analyzing: "连接中...",
      refreshing: "同步中...",
      metrics: "实时量化指标",
      pe: "市盈率", pb: "市净率", premium: "折溢价率", turnover: "换手率",
      strategy: "AI 智能投资顾问",
      shortTerm: "短线 / 投机",
      longTerm: "长线 / 价值",
      trend: "趋势 / 信号",
      risk: "风险预警",
      sentiment: "多空情绪",
      chartTitle: "180日 K线走势图",
      source: "行情源",
      high52: "180日最高",
      low52: "180日最低",
      rangeLabel: "时间跨度"
    }
  }[lang];

  const handleAnalyze = async (isDeepRefresh = false) => {
    if (!code) return;
    setError(null);
    if (isDeepRefresh) setRefreshing(true); else setLoading(true);

    try {
      const response = await fetch('/api/analyze-stock', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: code.trim().toUpperCase(), forceSearch: isDeepRefresh, lang })
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'System Overload');
      setData(result);
    } catch (e: any) {
      setError(`Critical: ${e.message}`);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    if (!data || !data.history || data.history.length === 0 || !mainCanvasRef.current) return;
    const canvas = mainCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    const kH = h * 0.85; 
    const paddingLeft = 75;
    const paddingRight = 40;
    const paddingTop = 75;
    const paddingBottom = 60;
    ctx.clearRect(0, 0, w, h);

    const hist = data.history;
    const maxP = Math.max(...hist.map(d => d.high || d.close)) * 1.01;
    const minP = Math.min(...hist.map(d => d.low || d.close)) * 0.99;
    const range = maxP - minP;
    const stepX = (w - paddingLeft - paddingRight) / hist.length;
    const getY = (p: number) => paddingTop + (1 - (p - minP) / (range || 1)) * (kH - paddingTop - 20);

    // Grid and Price Labels
    ctx.strokeStyle = 'rgba(34, 211, 238, 0.05)';
    ctx.font = '10px JetBrains Mono';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.textAlign = 'right';

    for (let i = 0; i <= 5; i++) {
       const gridY = paddingTop + (i / 5) * (kH - paddingTop - 20);
       const price = maxP - (i / 5) * range;
       ctx.beginPath(); ctx.moveTo(paddingLeft, gridY); ctx.lineTo(w - paddingRight, gridY); ctx.stroke();
       ctx.fillText(price.toFixed(3), paddingLeft - 15, gridY + 3);
    }

    // Candlesticks
    hist.forEach((d, i) => {
      const x = paddingLeft + i * stepX;
      const isUp = d.close >= d.open;
      const color = isUp ? '#f43f5e' : '#10b981';
      ctx.strokeStyle = color;
      ctx.beginPath(); ctx.moveTo(x + stepX*0.35, getY(d.high || d.close)); ctx.lineTo(x + stepX*0.35, getY(d.low || d.close)); ctx.stroke();
      ctx.fillStyle = color;
      const oY = getY(d.open); const cY = getY(d.close);
      ctx.fillRect(x, Math.min(oY, cY), stepX * 0.7, Math.max(1, Math.abs(oY - cY)));
    });

    // MAs
    const drawMA = (key: 'ma5'|'ma10'|'ma20', color: string) => {
      ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.beginPath();
      let first = true;
      hist.forEach((d, i) => {
        const val = (d as any)[key];
        if (val) {
          const x = paddingLeft + i * stepX + stepX * 0.35;
          const y = getY(val);
          if (first) { ctx.moveTo(x, y); first = false; } else ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    };
    drawMA('ma5', '#fbbf24'); drawMA('ma10', '#ec4899'); drawMA('ma20', '#3b82f6');
  }, [data, lang]);

  return (
    <div className="h-full flex flex-col p-6 overflow-y-auto custom-scrollbar bg-slate-950/40">
