      for (let i = 0; i < finalData.history.length; i++) {
        const calcMA = (period) => {
          if (i < period - 1) return null;
          const sum = finalData.history.slice(i - period + 1, i + 1).reduce((acc, curr) => acc + curr.close, 0);
