  if (/^[6]/.test(ticker)) return `1.${ticker}`; 
  if (/^[03]/.test(ticker)) return `0.${ticker}`; 
  if (/^[5]/.test(ticker)) return `1.${ticker}`; 
  if (/^[1]/.test(ticker)) return `0.${ticker}`; 
  return null;
